/* «Bola – odobi bilan aziz» kitobi asosida tuzilgan darslar va savollar.
   Har bir savolda: p — kitob beti, k — kitobdan aynan iqtibos (dastur bilan tekshirilgan).
   l — daraja (1: 7–11 yosh, 2: 12–15 yosh), g:"f" — faqat qiz bolalar uchun.
   s — bolalar uchun qisqa variant (savol, rasmli javoblar, bir gaplik izoh); story — dars oldidan rasmli kartochkalar. */
const BOOK = {"meta":{"title":"Bola – odobi bilan aziz","sub":"Farzand tarbiyalashda ota-onalarga maslahatlar","author":"Nashrga tayyorlovchi: Ziyovuddin Rahim","pub":"«Navro'z» nashriyoti","city":"Toshkent","year":2015,"isbn":"978-9943-381-40-7"},"units":[{"id":1,"title":"Odob oltindan qimmat","icon":"🌟","pages":[183,200],"lesson":[{"t":"Odob yaxshi ishlar va chiroyli so'zlardan iborat.","p":185},{"t":"Odob qoidalari ikkiga bo'linadi: shaxsiy odoblar va muomala qoidalari.","p":185},{"t":"Inson har bir ishni aql, odob va tartib asosida bajaradi. Odob aqlning mevasidir.","p":186},{"t":"Dono xalqimiz “odob oltindan qimmat” deydi: odobni boylik bilan sotib olib bo'lmaydi.","p":187},{"t":"Odobli bola erta turib yuz-qo'lini yuvadi, ota-onasiga salom berib, hol-ahvol so'raydi.","p":195},{"t":"Bolaga baho berilganda uning kiyimiga emas, odobiga qaraladi.","p":196}],"qs":[{"t":"mc","q":"Odob nimalardan iborat?","a":1,"e":"Kitobda odob yaxshi ishlar va chiroyli so'zlardan iborat, deyilgan. Shuning uchun har kuni yaxshi ish qilib, chiroyli gapiraylik.","p":185,"k":"Odob yaxshi ishlar va chiroyli so'zlardan iborat.","l":1,"o":["Boylik va chiroyli kiyimdan","Yaxshi ish va chiroyli so'zdan","Kuch va bahodirlikdan","Ko'p gapirishdan"],"s":{"q":"Odob nimalardan iborat?","e":"Odob — yaxshi ish va chiroyli so'z.","o":["💰 Boylik, kiyim","😊 Yaxshi ish, so'z","💪 Kuch","🗣️ Ko'p gapirish"]}},{"t":"mc","q":"Odob qoidalari nechaga bo'linadi?","a":2,"e":"Odob qoidalari ikkiga bo'linadi: shaxsiy odoblar va boshqalar bilan birga bajariladigan muomala qoidalari.","p":185,"k":"Demak, odob qoidalari ikkiga bo'linadi","l":2,"o":["Uchga: uy, ko'cha, maktab","Faqat bitta qoida bor","Ikkiga: shaxsiy va muomala","Beshga bo'linadi"],"s":{"q":"Odob qoidalari nechaga bo'linadi?","e":"Ikkiga: shaxsiy odob va muomala odobi.","o":["3️⃣ Uchga","1️⃣ Bitta","2️⃣ Ikkiga","5️⃣ Beshga"]}},{"t":"tf","q":"Shaxsiy odoblar — inson yolg'iz o'zi bajaradigan qoidalardir.","a":true,"e":"To'g'ri. Shaxsiy odoblarni inson o'zi bajaradi, muomala qoidalari esa boshqalar bilan birga bajariladi.","p":185,"k":"Shaxsiy odoblar har bir inson yolg'iz o'zi bajaradigan qoidalardir.","l":2,"s":{"q":"Shaxsiy odobni odam o'zi bajaradi.","e":"To'g'ri, shaxsiy odobni har kim o'zi bajaradi."}},{"t":"mc","q":"Inson hayvondan nimasi bilan farq qiladi?","a":3,"e":"Hayvonlar ham eydi, ichadi, uxlaydi. Ammo inson har bir ishni aql, odob va tartib bilan bajaradi.","p":186,"k":"Inson har bir ishni aql, odob va tartib asosida bajaradi.","l":1,"o":["Ko'p ovqat eyishi bilan","Uxlashi bilan","Suv ichishi bilan","Aql, odob va tartib bilan"],"s":{"q":"Odam hayvondan nimasi bilan farq qiladi?","e":"Odam har ishni aql, odob va tartib bilan qiladi.","o":["🍲 Ko'p yeyish","😴 Uxlash","💧 Suv ichish","🧠 Aql va odob"]}},{"t":"tf","q":"Kitobga ko'ra, odob boylikning mevasidir.","a":false,"e":"Noto'g'ri. Kitobda odob aqlning mevasi va hosilasi deyilgan. Aqlini to'g'ri ishlatgan bola odobli bo'ladi.","p":186,"k":"Demak, odob aqlning mevasi va hosilasidir.","l":2,"s":{"q":"Odob boylikning mevasidir.","e":"Yo'q, odob aqlning mevasidir."}},{"t":"mc","q":"«Qaysi biri yaxshiroq?» hikoyasida qariya qaysi bolani yaxshi bola dedi?","a":0,"e":"Qariya onasiga yordam berishga shoshilgan o'g'ilni yaxshi bola dedi. Ota-onaga yordam berish eng go'zal fazilatdir.","p":191,"k":"Onasiga yordam berishga shoshilgan o'g'ilni yaxshi bola desa bo'ladi","l":1,"o":["Onasiga yordam bergan bolani","Qo'lida tik yurgan bolani","Qo'shiq kuylagan bolani","Hech qaysi birini"],"s":{"q":"Hikoyada qariya qaysi bolani yaxshi dedi?","e":"Onasiga yordam bergan bola yaxshi bola.","o":["🧺 Onaga yordamchi","🤸 Qo'lda yurgan","🎤 Qo'shiqchi","🚫 Hech qaysi"]}},{"t":"tf","q":"Hikoyada uchinchi ayolning o'g'li onasining savatini o'zi ko'tarib ketdi.","a":true,"e":"To'g'ri. U maqtanmadi, balki onasiga yordam berdi. Yaxshilik so'zda emas, ishda ko'rinadi.","p":191,"k":"Oyijon, savatni menga bering, uni men ko'tarib boray","l":1,"s":{"q":"Hikoyadagi bola onasining savatini ko'tardi.","e":"To'g'ri, yaxshilik ishda ko'rinadi."}},{"t":"mc","q":"Luqmoni Hakim nasihatiga ko'ra kim hurmat-izzatga erishmaydi?","a":3,"e":"Luqmoni Hakim o'g'liga ilm o'rganishni buyurgan: kimda ilm bo'lmasa, hurmat-izzatga erishmaydi.","p":192,"k":"Ilm o'rgan, kimda ilm bo'lmasa, hurmat-izzatga etishmaydi.","l":2,"o":["Puli kam kishi","Kiyimi oddiy kishi","Yoshi kichik kishi","Ilmi bo'lmagan kishi"],"s":{"q":"Luqmoni Hakim: kim hurmat topmaydi?","e":"Ilm o'rgan: ilmsiz odam hurmat topmaydi.","o":["💸 Puli kam","👕 Kiyimi oddiy","👶 Yoshi kichik","📚 Ilmsiz odam"]}},{"t":"tf","q":"Luqmoni Hakim o'g'liga oftob chiqquncha uxlashni maslahat bergan.","a":false,"e":"Noto'g'ri. U aksincha, “oftob chiqquncha uxlama” deb nasihat qilgan. Erta turish yaxshi odatdir.","p":193,"k":"oftob chiqquncha uxlama, hadeb kulaverma","l":1,"s":{"q":"Luqmoni Hakim: oftob chiqquncha uxla, degan.","e":"Yo'q, u oftob chiqquncha uxlama, degan."}},{"t":"mc","q":"Odobli bola uyqudan turgach nima qiladi?","a":1,"e":"Odobli bola kiyinib, yuz-qo'lini yuvadi, so'ng ota-onasiga salom berib, hol-ahvol so'raydi.","p":195,"k":"ota-onasiga salom berib, ulardan hol-ahvol so'raydi.","l":1,"o":["Darhol ko'chaga o'ynashga chiqadi","Yuz-qo'lini yuvib, salom beradi","Yuz yuvmay ovqatga o'tiradi","Yana uxlab yotadi"],"s":{"q":"Odobli bola uyg'ongach nima qiladi?","e":"Yuz-qo'lini yuvib, ota-onasiga salom beradi.","o":["⚽ O'ynashga chiqadi","🧼 Yuvinib, salom","🍞 Yuvinmay yeydi","😴 Yana uxlaydi"]}},{"t":"tf","q":"Bolaga baho berilganda uning kiyimiga emas, odobiga qaraladi.","a":true,"e":"To'g'ri. Odobli bola ko'rimsiz bo'lsa ham hamma uni yaxshi ko'radi, chiroyli kiyim esa odobsizlikni yashirolmaydi.","p":196,"k":"bolaga baho berilganda hamma vaqt uning odobiga qaraladi, kiyimlariga emas.","l":2,"s":{"q":"Bolani kiyimiga emas, odobiga qarab baholaymiz.","e":"To'g'ri, odobli bolani hamma yaxshi ko'radi."}},{"t":"mc","q":"Kitobga ko'ra, qizning go'zalligi nimada?","a":2,"e":"Kitobda qizning hayosi uning go'zalligi deyilgan. Hayosi bor qiz oddiy kiyimda ham chiroyli ko'rinadi.","p":200,"k":"Qizning muomalasi uning husnidir. Qizning hayosi go'zalligidir.","l":2,"o":["Qimmat kiyimlarida","Ko'p yasanishida","Hayosida","Uzun sochlarida"],"g":"f","s":{"q":"Qizning go'zalligi nimada?","e":"Qizning hayosi — uning go'zalligi.","o":["👗 Qimmat kiyim","💄 Ko'p yasanish","🌸 Hayosida","💇 Uzun soch"]}}],"cards":[{"t":"Odob xulqni chiroyli qilish, so'z va harakatni tuzatishdir.","p":190},{"t":"Go'zal sifat va chiroyli xulq bilan bezanmagan kishini chiroyli kiyimlar hech qachon ko'rkam qilolmaydi.","p":190},{"t":"Kam gapir, oz egin va kam uxla.","p":188}],"story":[{"e":"🌟","t":"Odob — yaxshi ish va chiroyli so'z.","p":185},{"e":"🧠","t":"Odob aqlning mevasidir.","p":186},{"e":"💰","t":"Odob oltindan qimmat, uni pulga olib bo'lmaydi.","p":187},{"e":"🌅","t":"Odobli bola erta turib, salom beradi.","p":195}]},{"id":2,"title":"Shirin uyqu, erta tong","icon":"🌙","pages":[201,205],"lesson":[{"t":"Erta yotish yaxshi odat: erta yotgan bola barvaqt uyg'onadi.","p":201},{"t":"Yotishdan oldin tishlarni yuvish, chiroq va texnika asboblarini o'chirish kerak.","p":202},{"t":"O'ng tomonga yonboshlab, o'ng kaftni o'ng yuzga qo'yib yotiladi.","p":202},{"t":"Erta turishning aql, badan va iymonga foydasi bor.","p":203},{"t":"Uyg'ongach Yaratganga shukr qilinadi, o'rin yig'iladi va xona shamollatiladi.","p":203},{"t":"Luqmoni Hakim: yolg'on so'zlashdan ehtiyot bo'l, salomlashishga odatlan.","p":205}],"qs":[{"t":"mc","q":"Kitobga ko'ra, kechqurun soat nechada hamma bolalar uyquga yotgan bo'lishi kerak?","a":1,"e":"Kitobda kechqurun soat 9:00 da hamma bolalar uyquga yotgan bo'lishi kerak, deyilgan. Erta yotgan bola erta turadi.","p":201,"k":"Kechqurun soat 9:00da hamma bolalar uyquga yotgan bo'lishlari kerak.","l":1,"o":["Yarim tunda","Soat 9:00 da","Soat 12:00 da","Tong otganda"],"s":{"q":"Bolalar kechqurun soat nechada uxlaydi?","e":"Soat 9 da yotgan bola erta turadi.","o":["🌑 Yarim tunda","🕘 Soat 9 da","🕛 Soat 12 da","🌅 Tong otganda"]}},{"t":"tf","q":"Erta yotgan bola barvaqt uyg'onadi.","a":true,"e":"To'g'ri. Shuning uchun keraksiz o'yinlarga berilmasdan, vaqtida uxlash kerak.","p":201,"k":"Chunki erta yotgan bola barvaqt uyg'onadi.","l":1,"s":{"q":"Erta yotgan bola erta uyg'onadi.","e":"To'g'ri, shuning uchun vaqtida uxlaymiz."}},{"t":"mc","q":"Nega kompyuter va televizorni ishlatib bo'lgach darhol o'chirish kerak?","a":2,"e":"Ishlab turgan texnikadan ko'zga ko'rinmaydigan nurlar taraladi, ular sog'liqqa salbiy ta'sir qiladi.","p":202,"k":"Bu nurlar inson sog'lig'iga salbiy ta'sir qiladi.","l":2,"o":["Ular tez buzilib qoladi","Ovozi juda baland bo'ladi","Nurlari sog'liqqa zarar","Chiroq o'chib qoladi"],"s":{"q":"Televizorni nega darhol o'chiramiz?","e":"Texnika nuri sog'liqqa zarar qiladi.","o":["🔧 Tez buziladi","🔊 Ovozi baland","☢️ Nuri zararli","💡 Chiroq o'chadi"]}},{"t":"mc","q":"Uxlaganda qanday holatda yotish kerak?","a":3,"e":"Uyqu odobiga ko'ra o'ng tomonga yonboshlab, o'ng kaftni o'ng yuzga qo'yib yotiladi.","p":202,"k":"o'ng tomonga yonboshlab yotish; – o'ng kaftni o'ng yuzga qo'yib yotish.","l":1,"o":["Qorinni erga qaratib","Og'izda ovqat bilan","Kitob o'qib yonboshlab","O'ng tomonga yonboshlab"],"s":{"q":"Qanday holatda uxlaymiz?","e":"O'ng yonboshlab, o'ng kaftni yuzga qo'yib yotamiz.","o":["⬇️ Qorin bilan","🍬 Og'izda ovqat","📖 Kitob o'qib","👉 O'ng yonboshlab"]}},{"t":"tf","q":"Yonboshlab yotgan holda kitob o'qish uyqu odobiga kiradi.","a":false,"e":"Noto'g'ri. Kitobda yonboshlab olgan holda kitob o'qish noma'qul ishlar qatorida sanalgan.","p":202,"k":"yonboshlab olgan holda kitob o'qish.","l":2,"s":{"q":"Yotib kitob o'qish uyqu odobiga kiradi.","e":"Yo'q, yonboshlab kitob o'qish noma'qul."}},{"t":"tf","q":"Yotishdan avval tish va yuz-qo'lini yuvgan bola tinch uxlaydi.","a":true,"e":"To'g'ri. Kitobda bunday bola tinch uxlab, yomon tushlar ko'rmaydi, deyilgan.","p":202,"k":"Shunday qilgan bola tinch uxlaydi, yomon tushlar ko'rmaydi.","l":1,"s":{"q":"Tishini yuvib yotgan bola tinch uxlaydi.","e":"To'g'ri, u yomon tush ko'rmaydi."}},{"t":"mc","q":"Erta turish uchun uyquga yotayotgan bola nima deb niyat qiladi?","a":0,"e":"Erta turish uchun erta yotish, “ertalab barvaqt uyg'onaman” deb niyat qilish va kattalarga tayinlash kerak.","p":203,"k":"uyquga yotayotgan bola “ertalab barvaqt uyg'onaman”, deb niyat qilishi kerak","l":2,"o":["Ertalab barvaqt uyg'onaman","Kun chiqquncha uxlayman","Meni hech kim uyg'otmasin","Ertaga darsga bormayman"],"s":{"q":"Erta turish uchun nima deb niyat qilamiz?","e":"Erta turaman, deb niyat qilib yotamiz.","o":["⏰ Erta turaman","😴 Kech turaman","🙅 Uyg'otmanglar","🎒 Darsga bormayman"]}},{"t":"mc","q":"Aqlning tiniqlashib, yaxshi ishlaydigan vaqti qachon?","a":1,"e":"Tongda turgan bolaning aqli tiniq va o'tkir bo'ladi, darsida ham, ishlarida ham baraka bo'ladi.","p":203,"k":"Aqlning tiniqlashib, yaxshi ishlaydigan vaqti tong paytiga to'g'ri keladi.","l":2,"o":["Yarim tunda","Tong paytida","Tush paytida","Kechqurun"],"s":{"q":"Aql qachon yaxshi ishlaydi?","e":"Tongda aql tiniq bo'ladi, ishga baraka kiradi.","o":["🌑 Yarim tunda","🌅 Tongda","☀️ Tushda","🌆 Kechqurun"]}},{"t":"tf","q":"Uyg'ongandan so'ng o'rinni yig'ishtirmay turib ketsa ham bo'ladi.","a":false,"e":"Noto'g'ri. O'rinni yig'ishtirmay ketish noma'qul. O'rin-ko'rpalarni chiroyli qilib yig'ib qo'yish kerak.","p":204,"k":"O'rinni yig'ishtirmay turib ketish; 4. Yuz-qo'lni yuvmasdan boshqa ishga kirishish;","l":1,"s":{"q":"Turgach o'rinni yig'masa ham bo'ladi.","e":"Yo'q, o'rinni chiroyli yig'ib qo'yamiz."}},{"t":"mc","q":"Ertalab nega derazani bir oz ochib qo'yish kerak?","a":3,"e":"Tuni bilan xona dimiqib qoladi, shuning uchun derazani ochib havoni almashtirish kerak.","p":204,"k":"derazalarni bir oz ochib, havoni almashtirish kerak.","l":1,"o":["Qushlarni chaqirish uchun","Ko'chani tomosha qilish uchun","Xonani juda sovitish uchun","Xona havosini almashtirish"],"s":{"q":"Ertalab nega derazani ochamiz?","e":"Kechasi xona dimiqadi, havoni almashtiramiz.","o":["🐦 Qush chaqirish","👀 Ko'cha ko'rish","🥶 Xonani sovitish","🌬️ Havo almashadi"]}},{"t":"tf","q":"Luqmoni Hakimga ko'ra, so'z oltin, sukut esa kumushdir.","a":false,"e":"Noto'g'ri, aksincha: so'z kumush bo'lsa, sukut oltindir. Keraksiz gapirmaslik oltindek qimmatli.","p":205,"k":"So'z kumush bo'lsa, sukut oltindir.","l":2,"s":{"q":"Luqmoni Hakim: so'z oltin, sukut kumush.","e":"Yo'q, aksincha: so'z kumush, sukut oltin."}},{"t":"mc","q":"Luqmoni Hakim nega yolg'on so'zlashdan ehtiyot bo'lishni aytgan?","a":1,"e":"Yolg'on dinni buzadi va odamlar oldida obro'ni to'kadi. Shuning uchun to'g'ri so'zli bo'lish kerak.","p":205,"k":"yolg'on diningni buzadi va odamlar oldida obro'yingni to'kadi.","l":2,"o":["Tishga zarar beradi","Dinni buzib, obro'ni to'kadi","Uyquni qochiradi","Ko'zni charchatadi"],"s":{"q":"Yolg'on nega yomon?","e":"Yolg'on dinni buzadi, obro'ni to'kadi.","o":["🦷 Tishga zarar","💔 Obro'ni to'kadi","😵 Uyquni qochiradi","👁️ Ko'z charchaydi"]}}],"cards":[{"t":"So'z kumush bo'lsa, sukut oltindir.","p":205},{"t":"Agar qanoatli bo'lsang, dunyoda sendan boy odam bo'lmaydi.","p":205},{"t":"Ey o'g'lim, salomatlik bebaho boylik va go'zal axloq beqiyos ne'matdir.","p":205}],"story":[{"e":"🌙","t":"Soat 9 da uxlaymiz, erta turamiz.","p":201},{"e":"🛏️","t":"O'ng yonboshlab, o'ng kaftni yuzga qo'yib yotamiz.","p":202},{"e":"🌅","t":"Tongda aql tiniq bo'ladi.","p":203},{"e":"🤐","t":"So'z kumush, sukut oltin.","p":205}]},{"id":3,"title":"Ozodalik — sog'liq garovi","icon":"🧼","pages":[206,216],"lesson":[{"t":"Hojat qistaganda o'zini zo'riqtirish sog'liqqa zarar, o'yinni qo'yib vaqtida borish kerak.","p":207},{"t":"Hojatxonadan chiqqach, ikkala qo'l yaxshilab, iloji bo'lsa sovunlab yuviladi.","p":209},{"t":"Uxlashdan oldin va uyqudan turgach yuz, qo'l va oyoqlarni yuvish kerak.","p":211},{"t":"Sochiq, tish cho'tka, taroq kabi narsalar har kimning o'ziniki bo'lsin.","p":212},{"t":"Aksirganda yuzni chetga burib, og'iz va burunni dastro'mol bilan to'sish lozim.","p":214},{"t":"Tamaki va mast qiluvchi ichimliklar sog'liqqa katta zarar, ulardan uzoq bo'ling.","p":215}],"qs":[{"t":"tf","q":"Hojat qistaganda o'yinni davom ettirib, o'zini zo'riqtirish sog'liqqa zarar.","a":true,"e":"To'g'ri. O'yin qochib ketmaydi, sog'liq esa muhim. Hojat qistasa, darhol borish kerak.","p":207,"k":"hojati qistaganda o'zini zo'riqtirish sog'liqqa zarar.","l":1,"s":{"q":"Hojat qistasa, o'yinni davom ettirish zarar.","e":"To'g'ri, o'yinni qo'yib, darhol boramiz."}},{"t":"mc","q":"Hojatxonadan chiqqandan keyin nima qilinadi?","a":1,"e":"Hojatxonadan chiqqach ikkala qo'l yaxshilab, iloji bo'lsa, sovunlab yuviladi. Toza qo'l — sog'lom tana.","p":209,"k":"Hojatxonadan chiqqandan keyin ikkala qo'lni yaxshilab, iloji bo'lsa, sovunlab yuviladi.","l":1,"o":["Darhol ovqatga o'tiriladi","Qo'llar sovunlab yuviladi","Qo'l yuvish shart emas","Qo'l kiyimga artiladi"],"s":{"q":"Hojatxonadan chiqqach nima qilamiz?","e":"Qo'lni sovunlab yuvamiz: toza qo'l — sog'lom tana.","o":["🍲 Ovqat yeymiz","🧼 Qo'l yuvamiz","🚫 Yuvmaymiz","👕 Kiyimga artamiz"]}},{"t":"tf","q":"Suv jo'mragini chala burab ketsa ham hech narsa bo'lmaydi.","a":false,"e":"Noto'g'ri. Jo'mrak chala burab qoldirilsa, suv oqib isrof bo'ladi. Jo'mrakni yaxshilab o'chirish kerak.","p":209,"k":"Chala burab chiqib ketilsa, suv oqib, isrof bo'ladi.","l":2,"s":{"q":"Jo'mrakni chala burab ketsa bo'laveradi.","e":"Yo'q, suv oqib isrof bo'ladi."}},{"t":"mc","q":"Kitobga ko'ra, Alloh bergan sog'liqni saqlash kimning burchi?","a":1,"e":"Sog'liqni saqlash har bir odamning burchi. Ayniqsa bolalar bunga ko'proq ahamiyat berishi kerak.","p":210,"k":"Alloh tarafidan berilgan sog'liqni saqlash har bir odamning burchidir.","l":2,"o":["Faqat shifokorning","Har bir odamning","Faqat kattalarning","Faqat sportchining"],"s":{"q":"Sog'liqni saqlash kimning burchi?","e":"Sog'liqni saqlash har birimizning burchi.","o":["🩺 Shifokorning","🙋 Har bir odamning","👴 Kattalarning","🏅 Sportchining"]}},{"t":"tf","q":"Kattalar chekib yurgan bo'lsa, demak chekish zararsiz ekan.","a":false,"e":"Noto'g'ri. Kitobda bunday o'ylash xato deyilgan: ular odatni tashlay olmay qiynalayotgan bo'lishi mumkin.","p":210,"k":"Shuning uchun chekish va ichishga mutlaqo yaqin bormaslik kerak.","l":2,"s":{"q":"Kattalar cheksa, demak chekish zararsiz.","e":"Yo'q, chekishga umuman yaqin bormaymiz."}},{"t":"mc","q":"Qaysi narsalar faqat o'zingniki bo'lishi, uni boshqa odam ishlatmasligi kerak?","a":2,"e":"Sochiq, tish cho'tka, yostiq va taroq kabi narsalar har kimning o'ziniki bo'lishi kerak.","p":212,"k":"yostiq, yopinchiq va taroq kabi narsalar alohida o'zingniki bo'lsin","l":1,"o":["Maktab doskasi","Ko'chadagi o'rindiq","Tish cho'tka va taroq","Uyning eshigi"],"s":{"q":"Qaysi narsa faqat o'zingniki bo'ladi?","e":"Sochiq, tish cho'tka, taroq — har kimniki alohida.","o":["🏫 Maktab doskasi","🪑 Ko'cha o'rindig'i","🪥 Tish cho'tka","🚪 Uy eshigi"]}},{"t":"mc","q":"Nega ovqatga pashsha qo'nishidan ehtiyot bo'lish kerak?","a":3,"e":"Pashsha ko'pincha yuqumli kasallik mikroblarini olib yuradi va ularni odamga yuqtirishi mumkin.","p":212,"k":"u ko'pincha yuqumli kasallik mikroblarini olib yuradi","l":2,"o":["Ovqatni sovutib qo'yadi","Ovqatni yeb tugatadi","Ovqat rangini o'zgartiradi","Kasallik mikrobini tashiydi"],"s":{"q":"Pashsha ovqatga qo'nsa nega yomon?","e":"Pashsha kasallik mikrobini olib yuradi.","o":["🥶 Sovutadi","😋 Yeb tugatadi","🎨 Rang o'zgaradi","🦠 Mikrob tashiydi"]}},{"t":"mc","q":"Pashsha va changdan saqlanmagan holvani ko'chada egan bolaga nima bo'ldi?","a":0,"e":"Bola kasal bo'lib, kasalxonada bir oy yotdi. Ochiq, iflos joyda sotilgan ovqatni emaslik kerak.","p":212,"k":"Bir necha kundan keyin qattiq kasal bo'lib yotib qoldi","l":1,"o":["Qattiq kasal bo'lib qoldi","Kuchli va baquvvat bo'ldi","Do'stlari ko'paydi","Hech narsa bo'lmadi"],"s":{"q":"Ko'chada iflos holva yegan bola nima bo'ldi?","e":"Bola kasal bo'ldi. Iflos joyda ovqat yemaymiz.","o":["🤒 Kasal bo'ldi","💪 Kuchli bo'ldi","👫 Do'sti ko'paydi","🙂 Hech narsa"]}},{"t":"tf","q":"Aksirganda yoki yo'talganda yuzni chetga burish kerak.","a":true,"e":"To'g'ri. Og'iz va burunni dastro'mol yoki eng bilan to'sish ham lozim, chunki zararli moddalar otilib chiqadi.","p":214,"k":"Inson aksirganda yoki yo'talganda yuzini chetga burishi kerak.","l":1,"s":{"q":"Aksirganda yuzni chetga buramiz.","e":"To'g'ri, og'iz-burunni ro'mol bilan to'samiz."}},{"t":"mc","q":"Tishni har kuni necha marta yuvish kerak?","a":1,"e":"Tishni har kuni ikki marta misvok yoki pasta bilan yuvish kerak. Aks holda tish og'riydi va sarg'ayadi.","p":214,"k":"Tishni har kuni ikki marta misvok yoki","l":1,"o":["Haftada bir marta","Ikki marta","Hech qachon","Oyda bir marta"],"s":{"q":"Tishni kuniga necha marta yuvamiz?","e":"Kuniga ikki marta yuvsak, tish og'rimaydi.","o":["📅 Haftada bir","✌️ Ikki marta","🚫 Hech qachon","🗓️ Oyda bir"]}},{"t":"tf","q":"Kitobga ko'ra, hatto tamakining hidi ham o'ta zararli.","a":true,"e":"To'g'ri. Tamaki salomatlikning asosiy kushandasi. Uning o'rniga meva-sabzavot iste'mol qilish foydali.","p":215,"k":"Tamaki esa salomatligimizning asosiy kushandasidir. Hatto uning hidi ham o'ta zararli.","l":2,"s":{"q":"Hatto tamakining hidi ham zararli.","e":"To'g'ri, tamaki sog'liqning dushmani."}},{"t":"mc","q":"«Janjalkash bola» hikoyasida Zokir Haydarni xafa qilgach, oxirida nima bo'ldi?","a":2,"e":"Do'stlari tanbeh berganidan keyin Zokir pushaymon bo'ldi. Birovning ko'nglini og'ritish — qalbni kirlatadigan ish.","p":216,"k":"Zokir qilgan ishidan pushaymon bo'ldi...","l":2,"o":["O'yinda yutib chiqdi","Hamma uni maqtadi","Qilgan ishidan pushaymon bo'ldi","Haydar bilan urishdi"],"s":{"q":"Janjalkash Zokir oxirida nima bo'ldi?","e":"Birovni xafa qilish yomon, Zokir pushaymon bo'ldi.","o":["🏆 O'yinda yutdi","👏 Hamma maqtadi","😔 Pushaymon bo'ldi","👊 Urishdi"]}}],"cards":[{"t":"Tananing rohati taomning ozligidadir. Dilning rohati so'zning kamligidadir.","p":211},{"t":"Badantarbiyani tark etgan kishi yalqov va dangasa bo'lib qoladi.","p":211},{"t":"Doimo toza joylarda o'yna va sayr qil.","p":212}],"story":[{"e":"🧼","t":"Hojatxonadan keyin qo'lni sovunlab yuvamiz.","p":209},{"e":"🪥","t":"Tishni kuniga ikki marta yuvamiz.","p":214},{"e":"🤧","t":"Aksirganda yuzni chetga burib, og'izni yopamiz.","p":214},{"e":"🚭","t":"Tamaki sog'liqqa juda zarar.","p":215}]},{"id":4,"title":"Dasturxon odobi","icon":"🍽️","pages":[217,227],"lesson":[{"t":"Ovqatdan oldin qo'lni, kir bo'lsa-bo'lmasa, darhol yuvib olish kerak.","p":217},{"t":"Yoshi katta kishi yoki mehmon dasturxonga qo'l uzatishini kutib turiladi.","p":218},{"t":"Ovqat o'ng qo'l bilan, o'z oldidan, kichikroq luqma olib eyiladi.","p":218},{"t":"Ovqatdan keyin duo o'qiladi va ovqat tayyorlaganga rahmat aytiladi.","p":220},{"t":"Kunni yaxshi nonushta bilan boshlagan bolalar maktabda yaxshi o'qiydi.","p":224},{"t":"Halol rizq topish uchun avvalo halol mehnat qilish lozim.","p":225}],"qs":[{"t":"mc","q":"Ovqat eyishdan oldin nima qilish kerak?","a":1,"e":"Qo'l kir bo'lsa ham, bo'lmasa ham ovqatdan oldin darhol yuvib olish kerak va bunga doimo odatlanish lozim.","p":217,"k":"Ovqat eyishdan oldin qo'lni kir bo'lsa-bo'lmasa, darhol yuvib olish kerak","l":1,"o":["Ovqatni hidlab ko'rish","Qo'lni yuvib olish","Ovqatga darhol tashlanish","Televizorni yoqish"],"s":{"q":"Ovqatdan oldin nima qilamiz?","e":"Ovqatdan oldin doim qo'l yuvamiz.","o":["👃 Hidlab ko'ramiz","🧼 Qo'l yuvamiz","🏃 Darhol yeymiz","📺 Televizor"]}},{"t":"tf","q":"To'q qoringa ustma-ust ovqat eyish sog'liqqa foyda keltiradi.","a":false,"e":"Noto'g'ri. Faqat qorin ochganda ovqatlanish foydali, to'q qoringa ovqat eyish esa sog'liqqa zarar etkazadi.","p":217,"k":"To'q qoringa ustma-ust ovqat eyish sog'liqqa zarar etkazadi.","l":2,"s":{"q":"To'q qorinda yana ovqat yeyish foydali.","e":"Yo'q, bu sog'liqqa zarar."}},{"t":"mc","q":"Dasturxonda yoshi katta kishi yoki mehmon bo'lsa, nima qilinadi?","a":2,"e":"Kattalar va mehmonni hurmat qilib, ular dasturxonga qo'l uzatishini kutib turish odobdandir.","p":218,"k":"uning dasturxonga qo'l uzatishini kutib turiladi.","l":1,"o":["Hammadan oldin eyiladi","Yaxshi taom o'ziga olinadi","Ular qo'l uzatishi kutiladi","Indamay chiqib ketiladi"],"s":{"q":"Dasturxonda katta odam bo'lsa nima qilamiz?","e":"Kattalar boshlashini kutish — hurmat.","o":["🏃 Oldin yeymiz","🍗 Yaxshisini olamiz","⏳ Ularni kutamiz","🚪 Chiqib ketamiz"]}},{"t":"tf","q":"Ovqat eyishni “bismilloh”ni to'liq aytib boshlash kerak.","a":true,"e":"To'g'ri. Kattalar buni kichiklarga o'rgatib borishi kerak, “bismilloh” bilan taomga baraka kiradi.","p":218,"k":"“bismilloh”ni to'liq aytib, ovqat eyishni boshlashni","l":1,"s":{"q":"Ovqatni 'bismilloh' deb boshlaymiz.","e":"To'g'ri, 'bismilloh' bilan taomga baraka kiradi."}},{"t":"mc","q":"Taom qaysi qo'l bilan eyiladi?","a":3,"e":"Taom o'ng qo'l bilan eyiladi. Chap qo'lda ovqatlanish makruh ishlar qatorida sanalgan.","p":220,"k":"Taomni o'ng qo'li bilan eyish.","l":1,"o":["Chap qo'l bilan","Ikkala qo'l bilan","Farqi yo'q","O'ng qo'l bilan"],"s":{"q":"Ovqatni qaysi qo'l bilan yeymiz?","e":"O'ng qo'l bilan yeymiz.","o":["👈 Chap qo'l","🙌 Ikkala qo'l","🤷 Farqi yo'q","👉 O'ng qo'l"]}},{"t":"tf","q":"Ovqatni ayblash dasturxondagi yaxshi odatdir.","a":false,"e":"Noto'g'ri. Ovqatni ayblash o'zini tutishdagi makruh (yoqimsiz) ishlardan. Ovqat uchun shukr qilish kerak.","p":219,"k":"O'zini tutishdagi makruh ishlar: 1. Ovqatni ayblash;","l":2,"s":{"q":"Ovqatni ayblash yaxshi odat.","e":"Yo'q, ovqat uchun shukr qilamiz."}},{"t":"mc","q":"Nonga nisbatan qanday odob bor?","a":1,"e":"Nonni erga tashlamaslik, ustiga tovoq va boshqa idish qo'ymaslik kerak. Nonni ushlab ko'rish ham odobsizlik.","p":221,"k":"Nonni erga tashlamaslik, non ustiga tovoq va boshqa idishlarni qo'ymaslik.","l":2,"o":["Ustiga tovoq qo'yiladi","Erga tashlanmaydi","Ushlab yumshoqligi bilinadi","Ortganini tashlab yuboriladi"],"s":{"q":"Non odobi qaysi?","e":"Nonni yerga tashlamaymiz, ustiga idish qo'ymaymiz.","o":["🍽️ Ustiga tovoq","🚫 Yerga tashlamaymiz","🤏 Ushlab ko'ramiz","🗑️ Ortganini otamiz"]}},{"t":"mc","q":"Ko'p ovqat eb kasal bo'lgan o'quvchiga doktor oshqozonni nimaga o'xshatdi?","a":0,"e":"Hamyonga sig'ganidan ortiq pul solib bo'lmaganidek, qoringa sig'ganidan ortiq ovqat esa, kasal bo'lish mumkin.","p":223,"k":"Sening oshqozoning ham shu hamyonga o'xshaydi.","l":2,"o":["Pul to'la hamyonga","Katta qozonga","Bo'sh savatga","Suv to'la ko'zaga"],"s":{"q":"Doktor oshqozonni nimaga o'xshatdi?","e":"Qoringa sig'ganidan ko'p yesak, kasal bo'lamiz.","o":["👛 Hamyonga","🍲 Katta qozonga","🧺 Bo'sh savatga","🏺 Ko'zaga"]}},{"t":"tf","q":"«Bekinmachoq o'yini» hikoyasida Shokir qariyadan kechirim so'rab, uni manziliga olib bordi.","a":true,"e":"To'g'ri. Shokir kattaga hurmatsizlik qilganidan xijolat bo'lib, o'yinini tashladi va xatosini tuzatdi.","p":224,"k":"Nuroniy qariyaning ortidan yugurdi va undan kechirim so'radi.","l":1,"s":{"q":"Shokir qariyadan uzr so'rab, uni kuzatib qo'ydi.","e":"To'g'ri, Shokir kattaga hurmat ko'rsatdi."}},{"t":"mc","q":"Halol rizq topish uchun avvalo nima qilish lozim?","a":3,"e":"Halol rizq halol mehnat bilan topiladi. O'g'irlik, poraxo'rlik va qimor bilan topilgan pul harom.","p":225,"k":"Halol rizq topish uchun, avvalo halol mehnat qilish lozim.","l":1,"o":["Qimor o'ynash","Birovnikini olish","Ko'p uxlash","Halol mehnat qilish"],"s":{"q":"Halol rizq uchun nima qilish kerak?","e":"Halol rizq halol mehnat bilan topiladi.","o":["🎲 Qimor","🫳 Birovnikini olish","😴 Ko'p uxlash","💪 Halol mehnat"]}},{"t":"mc","q":"«Harom luqma» hikoyasida yosh Horis tushib qolgan xurmoni nega emadi?","a":2,"e":"Xurmo uni sotib olgan kishidan tushib qolgan edi. Horis birovning haqini eyish harom luqma ekanini bilardi.","p":226,"k":"Musulmon bolalariga harom luqmani edirasizmi?","l":2,"o":["Xurmo achchiq edi","U xurmoni yoqtirmasdi","Xurmo boshqa odamniki edi","Qorni juda to'q edi"],"s":{"q":"Horis tushgan xurmoni nega yemadi?","e":"Birovning haqini yeyish — harom luqma.","o":["😖 Achchiq edi","🙅 Yoqtirmasdi","👤 Birovniki edi","😋 Qorni to'q edi"]}},{"t":"tf","q":"Kitobga ko'ra, harom oz bo'lsa ham zarari ko'p bo'ladi.","a":true,"e":"To'g'ri. Shuning uchun kichik bo'lsa ham birovning haqiga yoki haromga qo'l cho'zmaslik kerak.","p":227,"k":"Harom oz bo'lsa ham zarari ko'pdir.","l":2,"s":{"q":"Harom oz bo'lsa ham zarari ko'p.","e":"To'g'ri, haromga qo'l cho'zmaymiz."}}],"cards":[{"t":"Ko'p eyish oz eyishdan ham mahrum qiladi.","p":223},{"t":"Badanning quvvati ovqat, ruhning quvvati ilmdir.","p":223},{"t":"Harom oz bo'lsa ham zarari ko'pdir.","p":227},{"t":"O'zi poku ko'zi pokni inson desa bo'ladi.","p":227}],"story":[{"e":"🧼","t":"Ovqatdan oldin qo'lni yuvamiz.","p":217},{"e":"👴","t":"Kattalar ovqatga qo'l uzatishini kutamiz.","p":218},{"e":"✋","t":"O'ng qo'l bilan, o'z oldimizdan yeymiz.","p":218},{"e":"🌾","t":"Halol rizq halol mehnat bilan topiladi.","p":225}]},{"id":5,"title":"Toza kiyim — pokiza tabiat","icon":"👕","pages":[228,234],"lesson":[{"t":"Kiyim avratni yopish, issiq-sovuqdan saqlanish va odamlarga chiroyli ko'rinish uchun kiyiladi.","p":228},{"t":"Kiyimni \"bismilloh\" deb, o'ng tomondan va shoshilmasdan kiyamiz; yechganda chap tomondan boshlaymiz.","p":228},{"t":"Yechilgan kiyim chiroyli taxlanib, shkafga qo'yiladi — duch kelgan joyga uloqtirilmaydi.","p":228},{"t":"Kiyim hashamli bo'lishi shart emas, lekin toza bo'lishi zarur.","p":231},{"t":"Aksirganda og'iz-burunni dastro'mol yoki salfetka bilan to'samiz.","p":233},{"t":"Yaxshilik qo'limizdan kelmasa, uni qila oladigan kishiga aytib, sababchi bo'lamiz.","p":234}],"qs":[{"t":"mc","q":"Kiyimni qaysi tomondan boshlab kiyish odob hisoblanadi?","a":1,"e":"Kitobda kiyimni o'ng tomondan boshlab kiyish odobi aytilgan.","p":228,"k":"Kiyim kiyishda “bismilloh”, deb aytish; 2. O'ng tomondan boshlab kiyish","l":1,"o":["Chap tomondan","O'ng tomondan","Farqi yo'q","Boshdan boshlab"],"s":{"q":"Kiyimni qaysi tomondan kiyamiz?","e":"Kiyimni o'ng tomondan boshlab kiyamiz.","o":["⬅️ Chapdan","➡️ O'ngdan","🤷 Farqi yo'q","🙆 Boshdan"]}},{"t":"mc","q":"Yechilgan kiyimlarni nima qilish kerak?","a":2,"e":"Yechilgan kiyim taxlab qo'yilsa, toza turadi va ertasiga oson topiladi.","p":228,"k":"Echilgan kiyimlar chiroyli qilib taxlab qo'yiladi.","l":1,"o":["Yerga tashlab qo'yish","Karavotga otib qo'yish","Chiroyli taxlab qo'yish","Eshik oldida qoldirish"],"s":{"q":"Yechgan kiyimni nima qilamiz?","e":"Taxlangan kiyim toza turadi, oson topiladi.","o":["⬇️ Yerga tashlaymiz","🛏️ Karavotga otamiz","🗂️ Taxlab qo'yamiz","🚪 Eshikda qoldiramiz"]}},{"t":"mc","q":"Kitobga ko'ra, kiyim kiyishdan maqsadlardan biri qaysi?","a":1,"e":"Kiyim uch maqsadda kiyiladi: avratni yopish, issiq-sovuqdan saqlanish va chiroyli ko'rinish.","p":228,"k":"Kiyim kiyishdan uch narsani maqsad qilinadi","l":2,"o":["Boshqalardan ustun ko'rinish","Issiq va sovuqdan saqlanish","Qimmat narsa ko'rsatish","Modaga ergashish"],"s":{"q":"Kiyimni nima uchun kiyamiz?","e":"Kiyim bizni issiq va sovuqdan saqlaydi.","o":["😎 Ustun ko'rinish","🌡️ Issiq-sovuqdan","💰 Qimmat narsa","👗 Moda uchun"]}},{"t":"mc","q":"Badan toza-yu, kiyim kir bo'lsa nima bo'ladi?","a":2,"e":"Kir kiyimdagi kir badanga o'tadi, shunda yuvinishning foydasi qolmaydi. Shuning uchun toza kiyim kiyamiz.","p":231,"k":"Kiyimdagi kirlar badanga o'tadi. Shundan keyin yuvinishning ham foydasi qolmaydi.","l":2,"o":["Hech narsa bo'lmaydi","Kiyim o'zi tozalanadi","Kirlar badanga o'tadi","Faqat ko'rinishi buziladi"],"s":{"q":"Kiyim kir bo'lsa nima bo'ladi?","e":"Kir kiyimdan kir badanga o'tadi, toza kiyamiz.","o":["🙂 Hech narsa","🫧 O'zi tozalanadi","🦠 Kir badanga o'tadi","👀 Faqat ko'rinish"]}},{"t":"mc","q":"Ko'ylakning qaysi qismi eng tez kir bo'ladi?","a":3,"e":"Yoqa va yeng eng tez kirlanadi, shuning uchun ularni tez-tez tekshirib turish kerak.","p":232,"k":"Ko'ylakning eng ko'p kir bo'ladigan qismi yoqasi va engi","l":2,"o":["Orqasi","Cho'ntagi","Tugmalari","Yoqasi va yengi"],"s":{"q":"Ko'ylakning qayeri tez kirlanadi?","e":"Yoqa va yengni tez-tez tekshirib turamiz.","o":["🔙 Orqasi","👖 Cho'ntagi","🔘 Tugmalari","👔 Yoqa va yengi"]}},{"t":"mc","q":"Avtobusda birdan aksirib qolsangiz nima qilinadi?","a":0,"e":"Aksirganda burunni dastro'mol yoki salfetka bilan to'sish boshqalarni hurmat qilishdir.","p":233,"k":"burunni dastro'mol yoki salfetka bilan to'siladi, keyin unga artiladi","l":1,"o":["Dastro'mol bilan to'siladi","Odamlarga qarab aksiriladi","Burun kiyimga artiladi","Hech narsa qilinmaydi"],"s":{"q":"Avtobusda aksirsang nima qilasan?","e":"Burunni to'sish boshqalarni hurmat qilishdir.","o":["🤧 Dastro'mol tutaman","😮 Odamga qarayman","👕 Kiyimga artaman","🤷 Hech narsa"]}},{"t":"mc","q":"Ahmad kambag'al bolaga qanday yordam berdi?","a":1,"e":"Ahmad o'zi yordam bera olmasa ham, muhtojlarga yordam beradigan tashkilotga borib, do'sti haqida aytdi.","p":234,"k":"to'ppa-to'g'ri muhtojlarga yordam beradigan tashkilot tomon ketdi","l":1,"o":["Unga e'tibor bermadi","Yordam tashkilotiga aytdi","Etigini yechib berdi","Uni masxara qildi"],"s":{"q":"Ahmad kambag'al bolaga qanday yordam berdi?","e":"Ahmad yordam beradigan tashkilotga borib aytdi.","o":["🙈 E'tibor bermadi","🏢 Tashkilotga aytdi","👢 Etigini berdi","😝 Masxara qildi"]}},{"t":"tf","q":"Kiyimni shoshilmasdan, avaylab kiyish kerak.","a":true,"e":"Shoshilsak, kiyimni teskari kiyib yoki tugmasini uzib qo'yishimiz mumkin.","p":228,"k":"Kiyimni shoshilmasdan kiyish. Agar shoshilsang, kiyimni teskari kiyishing","l":1,"s":{"q":"Kiyimni shoshilmasdan kiyish kerak.","e":"Shoshilsak, kiyimni teskari kiyib qo'yamiz."}},{"t":"tf","q":"Kiyim albatta qimmat va hashamli bo'lishi shart.","a":false,"e":"Kitobda kiyim hashamli bo'lishi shart emas, lekin toza bo'lishi zarurligi aytilgan.","p":231,"k":"Kiyim hashamli bo'lishi shart emas, ammo toza bo'lishi zarur.","l":2,"s":{"q":"Kiyim albatta qimmat bo'lishi kerak.","e":"Kiyim qimmat bo'lishi shart emas, toza bo'lsin."}},{"t":"tf","q":"Ko'chadan kelganda ustki kiyimdagi changni qoqib, keyin uyga kiriladi.","a":true,"e":"Ustki kiyimni tozalab kirsak, uy ham, kiyim ham toza qoladi.","p":232,"k":"Agar chang o'tirgan bo'lsa, qoqib tozalanadi.","l":2,"s":{"q":"Ko'chadan kelib, kiyim changini qoqamiz.","e":"Changni qoqsak, uy ham, kiyim ham toza qoladi."}},{"t":"tf","q":"Ovqat yeb bo'lgach, qo'lni kiyimga artsa bo'ladi.","a":false,"e":"Kitobda buni beadablik deyilgan: kiyimda dog' qoladi va yuvsa ham ketmaydi.","p":232,"k":"Yana ba'zi bolalar beadabligi bois ovqatni eb, qo'lini kiyimiga artadilar.","l":1,"s":{"q":"Ovqatdan keyin qo'lni kiyimga artsa bo'ladi.","e":"Bu beadablik, kiyimda dog' qoladi."}},{"t":"tf","q":"Yaxshi ishga yo'l ko'rsatgan kishi ham uni qilgan kishi kabi savob oladi.","a":true,"e":"Ahmad o'zi qila olmagan yaxshilikka sababchi bo'ldi va shu bilan savob topdi.","p":234,"k":"savobli ishga yo'llovchi uni qiluvchi kabi savobga ega bo'ladi","l":2,"s":{"q":"Yaxshi ishga yo'l ko'rsatgan ham savob oladi.","e":"Yaxshilikka sababchi bo'lish ham savobdir."}}],"cards":[{"t":"Kiyim hashamli bo'lishi shart emas, ammo toza bo'lishi zarur.","p":231},{"t":"Chiroyli va ozoda kiyinish ham maqtalgan sifatlardandir.","p":228},{"t":"Savobli ishga yo'llovchi uni qiluvchi kabi savobga ega bo'ladi.","p":234}],"story":[{"e":"👕","t":"Kiyimni o'ng tomondan, shoshilmasdan kiyamiz.","p":228},{"e":"🗂️","t":"Yechgan kiyimni chiroyli taxlab qo'yamiz.","p":228},{"e":"✨","t":"Kiyim qimmat bo'lmasa ham, toza bo'lsin.","p":231},{"e":"🤝","t":"Yaxshilikka yo'l ko'rsatgan ham savob oladi.","p":234}]},{"id":6,"title":"Tartibli xona — toza uy","icon":"🧹","pages":[235,243],"lesson":[{"t":"Narsalarni toza tutishning birinchi sharti — tartib: har bir narsa o'z joyida turadi.","p":235},{"t":"Toza buyum uzoq xizmat qiladi: uy tartibli bo'ladi, kasallikdan saqlanamiz, pul tejaladi.","p":235},{"t":"Kitobga chizmaymiz, varaqlarini buklamaymiz; o'qib bo'lgach joyiga qo'yamiz.","p":236},{"t":"Qalam va o'yinchoqni sindirish — ota-ona peshana teri bilan topgan ne'matni isrof qilishdir.","p":236},{"t":"Bolalar xonasini har kuni yig'ishtirib, shamollatib turamiz.","p":241},{"t":"Yaxshi kishi bor narsasini qo'shnisi bilan baham ko'radi.","p":243}],"qs":[{"t":"mc","q":"Narsalarni toza tutish uchun birinchi shart nima?","a":1,"e":"Tartib — har bir narsani o'z joyiga qo'yish. Shunda narsalar toza va oson topiladi.","p":235,"k":"Tartib har bir narsani joy-joyiga qo'yishdir.","l":1,"o":["Ko'p pul","Tartib","Yangi buyumlar","Katta uy"],"s":{"q":"Narsalarni toza tutishning birinchi sharti?","e":"Tartib — har narsani o'z joyiga qo'yish.","o":["💵 Ko'p pul","📦 Tartib","🆕 Yangi buyum","🏠 Katta uy"]}},{"t":"mc","q":"Buyumlarni toza tutishning uchta foydasi qaysi?","a":2,"e":"Toza buyum uyni tartibli qiladi, kasallikdan saqlaydi va pulni tejaydi.","p":235,"k":"uyning tartibli bo'lishi, kasallikdan saqlanish va pulning tejalishi","l":2,"o":["Maqtov, sovg'a, dam olish","Ko'p o'yin, kam dars","Tartib, sog'liq, pul tejash","Faqat chiroyli ko'rinish"],"s":{"q":"Buyumni toza tutishning foydasi nima?","e":"Toza buyum tartib, sog'liq va pul tejaydi.","o":["🎁 Maqtov, sovg'a","⚽ Ko'p o'yin","✅ Tartib, sog'liq","🪞 Faqat chiroy"]}},{"t":"mc","q":"Daftarga siyoh bilan xato yozilsa nima qilinadi?","a":3,"e":"Xatoni tirnoq bilan o'chirsak, daftar xunuk bo'ladi; bir chiziq tortish kifoya.","p":236,"k":"Uning ustidan bir chiziq tortiladi","l":1,"o":["Tirnoq bilan o'chiriladi","Varaq yirtib tashlanadi","Ustiga rasm chiziladi","Ustidan bir chiziq tortiladi"],"s":{"q":"Daftarda siyoh bilan xato yozsang-chi?","e":"Xato ustidan bir chiziq tortish kifoya.","o":["💅 Tirnoqda o'chir","📄 Varaqni yirt","🎨 Rasm chiz","➖ Chiziq tort"]}},{"t":"mc","q":"Sochiq va tish cho'tkasi qanday bo'lishi kerak?","a":0,"e":"Har bir bolaning sochig'i va tish cho'tkasi alohida bo'ladi — bu ozodalik va sog'liq uchun muhim.","p":237,"k":"Har bir bolaning sochiq va tish cho'tkasi alohida bo'ladi.","l":1,"o":["Har kimniki alohida","Hamma uchun bitta","Akasi bilan umumiy","Ular kerak emas"],"s":{"q":"Sochiq va tish cho'tkasi qanday bo'ladi?","e":"Har kimning sochig'i alohida — bu sog'liq uchun.","o":["🪥 Har kimga alohida","👪 Hammaga bitta","👦 Aka bilan umumiy","🚫 Kerak emas"]}},{"t":"mc","q":"Kompyuterni ishlatib bo'lgach nima qilinadi?","a":1,"e":"Texnikani tokdan o'chirib, changini artib tursak, u uzoq va yaxshi ishlaydi.","p":237,"k":"Kompyuter kabi texnika asboblarni ishlatib bo'lgach, albatta tokdan o'chiriladi.","l":2,"o":["Yoqilgan holda qoldiriladi","Tokdan o'chiriladi","Suv bilan yuviladi","Ustiga kitob qo'yiladi"],"s":{"q":"Kompyuterdan keyin nima qilamiz?","e":"Tokdan o'chirilgan texnika uzoq ishlaydi.","o":["💡 Yoqiq qoldiramiz","🔌 Tokdan o'chiramiz","💧 Suvda yuvamiz","📚 Kitob qo'yamiz"]}},{"t":"mc","q":"Mehmonxona nima uchun pokiza va chiroyli bo'lishi kerak?","a":1,"e":"Toza uy mehmonning ko'nglini ko'taradi; bu mehmonni hurmat qilishdir.","p":240,"k":"pokiza va chiroyli bo'lishi mehmon hurmati uchun qilinadi","l":2,"o":["Faqat maqtanish uchun","Mehmon hurmati uchun","Bolalar o'ynashi uchun","Kiyim saqlash uchun"],"s":{"q":"Mehmonxona nega toza bo'lishi kerak?","e":"Toza uy — mehmonga hurmat.","o":["😏 Maqtanish uchun","🤝 Mehmon hurmati","🧸 O'ynash uchun","👕 Kiyim uchun"]}},{"t":"mc","q":"Hikoyada Zokir ertasi kuni Muhammadnikiga nima olib bordi?","a":2,"e":"Zokir ovqatini Muhammad va onasi bilan baham ko'rdi. Yaxshi kishi bor narsasini qo'shnisi bilan bo'lishadi.","p":243,"k":"onasi tayyorlagan ovqatni ko'tarib Muhammadning uyiga bordi","l":1,"o":["O'yinchoqlarini","Kitoblarini","Onasi pishirgan ovqatni","Yangi kiyimlarni"],"s":{"q":"Zokir qo'shnisiga nima olib bordi?","e":"Zokir ovqatini qo'shnisi bilan baham ko'rdi.","o":["🧸 O'yinchoq","📚 Kitob","🍲 Ovqat","👕 Kiyim"]}},{"t":"tf","q":"Qalamni tishlab buzish — ota-ona topgan ne'matni isrof qilishdir.","a":true,"e":"Ota-onamiz buyumlarni mehnat bilan topadi, ularni asrash ne'matni qadrlashdir.","p":236,"k":"Bu ota-onasi peshana teri bilan topgan ne'matni isrof qilishdir.","l":2,"s":{"q":"Qalamni tishlab buzish — isrof.","e":"Ota-ona mehnat bilan olgan narsani asraymiz."}},{"t":"tf","q":"Kitob varaqlarini buklash va unga ermak uchun chizish mumkin.","a":false,"e":"Kitob ulug' ne'mat, unga chizish, varaqlarini buklash yoki yirtish mumkin emas.","p":236,"k":"uning varaqlarini buklashi yoki yirtishi mumkin emas","l":1,"s":{"q":"Kitobni buklasa, unga chizsa bo'ladi.","e":"Kitob ulug' ne'mat, uni asraymiz."}},{"t":"tf","q":"Odobli bola uyqudan turgach, ko'rpa-to'shagini taxlab qo'yadi.","a":true,"e":"Har kuni o'rnini yig'ishtirish xonani tartibli va toza saqlaydi.","p":237,"k":"ko'rpa-to'shaklarini yig'ishtirib, ularni chiroyli qilib taxlab qo'yadi","l":1,"s":{"q":"Odobli bola o'rnini taxlab qo'yadi.","e":"O'rinni yig'ishtirsak, xona toza bo'ladi."}},{"t":"tf","q":"Dars qilayotganda o'yinchoq o'ynash ham foydali.","a":false,"e":"Dars paytida o'ynash noto'g'ri; darsni to'liq tayyorlab bo'lgach, biroz o'ynash foydali.","p":238,"k":"Dars paytida o'yinchoq o'ynash noto'g'ri.","l":2,"s":{"q":"Dars paytida o'yinchoq o'ynash foydali.","e":"Avval dars, keyin biroz o'yin."}},{"t":"tf","q":"O'zimiz to'q bo'lsak, qo'shnimiz och qolsa ham bo'laveradi.","a":false,"e":"Hadisi sharifda qo'shnisi och ekanini bilib, o'zi to'q holda tunagan kishi qoralangan.","p":243,"k":"o'zi to'q bo'lib yon qo'shnisi och holda ekanini bilib turib tunni o'tkazsa","l":2,"s":{"q":"Qo'shnim och qolsa ham, men to'q bo'lsam bo'ldi.","e":"Qo'shni och bo'lsa, yordam berishimiz kerak."}}],"cards":[{"t":"Uy osoyishtaligi bebaho ne'mat.","p":239},{"t":"Ozoda va sarishtali hovli-joyda baraka va rohat bo'ladi.","p":239},{"t":"Yaxshi kishilar o'zidagi bor narsalarni qo'shnilari bilan baham ko'rishlari kerak.","p":243}],"story":[{"e":"📦","t":"Tartib — har narsa o'z joyida turadi.","p":235},{"e":"🧽","t":"Toza buyum uzoq xizmat qiladi, pul tejaladi.","p":235},{"e":"📚","t":"Kitob, qalam — ota-ona mehnati, ularni asraymiz.","p":236},{"e":"🍲","t":"Yaxshi kishi bor narsasini qo'shnisi bilan bo'lishadi.","p":243}]},{"id":7,"title":"Uyda, maktabda, ko'chada","icon":"🎒","pages":[244,249],"lesson":[{"t":"Uyda oila a'zolariga salom beramiz, ota-onaga itoat qilamiz, kichiklarga mehribon bo'lamiz.","p":244},{"t":"Darsda savol yoki javob bermoqchi bo'lsak, o'ng qo'limizni ko'taramiz.","p":245},{"t":"Birovning narsasini so'ramasdan olmaymiz, olganimizni darrov qaytaramiz.","p":246},{"t":"Bugungi ishni ertaga qoldirmaymiz.","p":246},{"t":"Ko'chada piyodalar yo'lakchasidan yuramiz, zaif kishiga yo'ldan o'tishda yordam beramiz.","p":248},{"t":"Haqiqiy pahlavon — g'azablanganda o'zini bosib tura olgan kishi.","p":249}],"qs":[{"t":"mc","q":"Maktabdan qaytganda va uyg'onganda oila a'zolariga nima qilinadi?","a":2,"e":"Salom berish oilada mehr va hurmatni oshiradi.","p":244,"k":"uxlashdan oldin va uyqudan turganingda oila a'zolaringga salom ber","l":1,"o":["Indamay o'tiladi","Sovg'a so'raladi","Salom beriladi","Shikoyat qilinadi"],"s":{"q":"Uyg'onganda oilaga nima qilamiz?","e":"Salom oilada mehrni oshiradi.","o":["😶 Indamaymiz","🎁 Sovg'a so'raymiz","👋 Salom beramiz","😠 Shikoyat qilamiz"]}},{"t":"mc","q":"Darsda savol bermoqchi bo'lsangiz nima qilinadi?","a":0,"e":"Qo'l ko'tarib, o'qituvchi ruxsat bergach, turib javob berish — dars odobi.","p":245,"k":"Savol yoki javob bermoqchi bo'lsang, o'ng qo'lingni ko'tar.","l":1,"o":["O'ng qo'l ko'tariladi","Baland ovozda gapiriladi","Do'stga shivirlanadi","Joydan sakraladi"],"s":{"q":"Darsda savol bermoqchimisan?","e":"Qo'l ko'tarib, ruxsat kutish — dars odobi.","o":["✋ O'ng qo'l ko'tar","📢 Baland gapir","🤫 Do'stga shivirla","🦘 Joydan sakra"]}},{"t":"mc","q":"Kattalarni nima sababdan hurmat qilish kerak?","a":1,"e":"Kattalarni qo'rqqanimiz uchun emas, yoshi ulug', ilmi va tajribasi ko'pligi uchun hurmat qilamiz.","p":245,"k":"yoshi sendan ulug'ligi, ilmi va tajribasi ko'proqligi sabab ularga hurmat bajo keltir","l":2,"o":["Faqat qo'rqqani uchun","Yoshi, ilmi, tajribasi uchun","Sovg'a berishi uchun","Kuchli bo'lgani uchun"],"s":{"q":"Kattalarni nega hurmat qilamiz?","e":"Kattalarning yoshi, ilmi va tajribasi ko'p.","o":["😨 Qo'rqqanimiz uchun","👴 Yoshi va ilmi","🎁 Sovg'asi uchun","💪 Kuchli bo'lgani"]}},{"t":"mc","q":"Bir ishni keyingi kunga qoldirsak nima bo'ladi?","a":3,"e":"Har kunning o'z ishi bor; qoldirilgan ish boshqalarini ham orqaga suradi.","p":246,"k":"Birini keyingi kunga qoldirsang, barcha ishlaring orqaga surilib ketaveradi.","l":2,"o":["Ish o'zi bajarilib qoladi","Vaqt ko'payib ketadi","Hech narsa bo'lmaydi","Barcha ishlar orqaga suriladi"],"s":{"q":"Ishni ertaga qoldirsak nima bo'ladi?","e":"Qoldirilgan ish boshqa ishlarni ham suradi.","o":["✨ O'zi bajariladi","⏳ Vaqt ko'payadi","🙂 Hech narsa","⏪ Ishlar suriladi"]}},{"t":"mc","q":"Hikoyadagi o'quvchi qanday yomon odat chiqardi?","a":1,"e":"Kech qolgani sabab u darslarni tushunmay qoldi. Maktabga o'z vaqtida borish muhim.","p":247,"k":"maktabga kech qolib keladigan odat chiqardi","l":1,"o":["Kitob o'qishni","Maktabga kech qolishni","Darsni takrorlashni","Erta uxlashni"],"s":{"q":"Hikoyadagi o'quvchi qanday odat chiqardi?","e":"Maktabga o'z vaqtida boramiz.","o":["📖 Kitob o'qish","⏰ Kech qolish","🔁 Dars takrori","😴 Erta uxlash"]}},{"t":"mc","q":"Ko'chada bilmasdan birovni turtib yuborsangiz nima qilasiz?","a":2,"e":"Bilmasdan ozor yetkazsak ham, muloyimlik bilan kechirim so'rash kerak.","p":249,"k":"uning oyoq kiyimini bosib olsang, muloyimlik bilan kechirim so'ra.","l":2,"o":["Indamay ketaveraman","Uni ayblayman","Kechirim so'rayman","Kulib qo'yaman"],"s":{"q":"Bilmasdan birovni turtib yubording-chi?","e":"Bilmasdan bo'lsa ham, kechirim so'raymiz.","o":["🚶 Ketaveraman","👉 Uni ayblayman","🙏 Kechirim so'rayman","😂 Kulaman"]}},{"t":"mc","q":"Hadisga ko'ra haqiqiy pahlavon kim?","a":2,"e":"Kuch — g'azab kelganda o'zini tuta bilishda. Xolid kuchli bo'lsa ham, o'zini tuta olmadi.","p":249,"k":"g'azab kelganida o'zini bosib tura olgan haqiqiy pahlavondir","l":2,"o":["Raqibini yenggan kishi","Eng kuchli bola","G'azabda o'zini bosgan","Stulni ko'targan bola"],"s":{"q":"Haqiqiy pahlavon kim?","e":"Kuch — g'azabda o'zini tuta bilishda.","o":["🥊 Raqibni yenggan","💪 Eng kuchli bola","😌 O'zini bosgan","🪑 Stul ko'targan"]}},{"t":"tf","q":"Uyda koptok tepib, baqirib qo'shnilarni bezovta qilsa bo'ladi.","a":false,"e":"Uyda shovqin qilib, uydagilar va qo'shnilarga ozor berish odobsizlikdir.","p":244,"k":"Koptok tepib, ko'p baqirib yoki yugirib uydagilarga ham, qo'ni-qo'shnilarga ham ozor berma.","l":1,"s":{"q":"Uyda baqirib, qo'shnini bezovta qilsa bo'ladi.","e":"Shovqin bilan birovga ozor bermaymiz."}},{"t":"tf","q":"Sinfdoshning narsasini so'ramay olish o'g'rilikka yo'l ochishi mumkin.","a":true,"e":"Birovning narsasi kerak bo'lsa, egasidan so'rab olamiz va darrov qaytaramiz.","p":246,"k":"so'ramasdan tegma, ularning jihoz va buyumlarini titma. Zero, bu o'g'rilikka yo'l ochishi mumkin.","l":2,"s":{"q":"So'ramay birov narsasini olish yomon yo'l.","e":"So'rab olamiz va darrov qaytaramiz."}},{"t":"tf","q":"Kitobda odob bolaning eng chiroyli libosi deyilgan.","a":true,"e":"Chiroyli kiyimdan ko'ra odob, a'lo o'qish va hurmat bolani yaxshi ko'rsatadi.","p":247,"k":"odob bolaning eng chiroyli libosidir","l":1,"s":{"q":"Odob bolaning eng chiroyli libosi.","e":"Odobli bola hammaga yoqadi."}},{"t":"tf","q":"Hikoyadagi bola keyin vaqtini behuda o'tkazganiga afsuslandi.","a":true,"e":"O'qishni tashlagan bola a'lochi sinfdoshlariga havas bilan qarab afsuslandi. Vaqtni qadrlash kerak.","p":248,"k":"ularga havas bilan qarab, vaqtini behuda ketkazganiga afsuslanardi","l":2,"s":{"q":"Hikoyadagi bola vaqtini behuda o'tkazib afsuslandi.","e":"Vaqtni qadrlaymiz, o'qishni tashlamaymiz."}},{"t":"tf","q":"Xolid jahli chiqib, o'rtog'ini urgani to'g'ri ish edi.","a":false,"e":"Kitobda Xolidning ishini oqlab bo'lmasligi aytilgan: g'azabni bosish kerak edi.","p":249,"k":"Xolidning bu ishini oqlab bo'lmaydi.","l":1,"s":{"q":"Xolid jahl bilan o'rtog'ini urib to'g'ri qildi.","e":"Jahl chiqqanda o'zimizni bosishimiz kerak."}}],"cards":[{"t":"Odob bolaning eng chiroyli libosidir.","p":247},{"t":"Bugungi ishni ertaga qoldirma.","p":246},{"t":"Raqibini enggan pahlavon emas, balki g'azab kelganida o'zini bosib tura olgan haqiqiy pahlavondir","p":249}],"story":[{"e":"👋","t":"Uyda oilamizga salom beramiz.","p":244},{"e":"✋","t":"Darsda gapirmoqchi bo'lsak, o'ng qo'lni ko'taramiz.","p":245},{"e":"⏰","t":"Bugungi ishni ertaga qoldirmaymiz.","p":246},{"e":"💪","t":"Haqiqiy pahlavon — g'azabda o'zini bosa olgan.","p":249}]},{"id":8,"title":"Ota-ona — eng aziz inson","icon":"👪","pages":[249,255],"lesson":[{"t":"Ona farzandini to'qqiz oy ko'tarib, tunlari bedor o'tirib parvarish qilgan.","p":250},{"t":"Ota qiynalib mehnat qilib, ovqat, kiyim va o'qishimizni ta'minlaydi — u bizga tayanch.","p":250},{"t":"Ota-onaga yaxshilikning avvali — itoat. Ularga \"uf\" demaymiz, chaqirsa \"labbay\" deymiz.","p":252},{"t":"Ota-onaning kambag'alligi ayb emas, farzandning odobsizligi katta ayb.","p":253},{"t":"Qiyin holatga tushsak, rostini aytib, ota-onamizga xabar beramiz.","p":255}],"qs":[{"t":"mc","q":"\"Labbay\" so'zi aslida nimani anglatadi?","a":1,"e":"Ota-ona chaqirganda \"labbay\" deyish — hurmat va tayyorlik belgisi.","p":251,"k":"aslida “labbay” so'zi “mana, huzuringdaman” ma'nosini anglatadi","l":1,"o":["Sendan bezorman","Mana, huzuringdaman","Keyinroq kelaman","Bilmayman"],"s":{"q":"\"Labbay\" so'zi nimani anglatadi?","e":"\"Labbay\" — hurmat va tayyorlik belgisi.","o":["😒 Bezorman","🙋 Huzuringdaman","⏳ Keyin kelaman","🤷 Bilmayman"]}},{"t":"mc","q":"Ota-ona chaqirganda nima deb javob beriladi?","a":2,"e":"\"Labbay\" deb, tezda ularning huzuriga borish kerak.","p":251,"k":"Chaqirganlarida “labbay”, deb tezda huzurlariga etib bor.","l":1,"o":["Uf","Hozir emas","Labbay","Keyin"],"s":{"q":"Ota-ona chaqirsa nima deymiz?","e":"\"Labbay\" deb, tez yonlariga boramiz.","o":["😤 Uf","✋ Hozir emas","🙋 Labbay","⏳ Keyin"]}},{"t":"mc","q":"Ota-onaga yaxshilik qilishning avvali nima?","a":1,"e":"Ota-ona bolasini zararli narsaga buyurmaydi, shuning uchun ularga itoat qilamiz.","p":252,"k":"Ota-onaga yaxshilik qilishning avvali ularga itoatli bo'lishdir.","l":2,"o":["Qimmat sovg'a olish","Ularga itoatli bo'lish","Ko'p pul topish","Uzoqroqda yashash"],"s":{"q":"Ota-onaga yaxshilikning avvali nima?","e":"Ota-ona yomonlikka buyurmaydi, itoat qilamiz.","o":["🎁 Qimmat sovg'a","👂 Itoatli bo'lish","💵 Ko'p pul","🏠 Uzoqda yashash"]}},{"t":"mc","q":"Kitobda ota farzandi uchun kim deb ataladi?","a":0,"e":"Ota mehnat qilib, o'qitib, kasal bo'lsak davolatadi — u bizning tayanchimiz.","p":250,"k":"Demak, otang sen uchun tayanchdir.","l":1,"o":["Tayanch","Mehmon","Begona","Qo'riqchi"],"s":{"q":"Ota farzandi uchun kim?","e":"Ota bizni boqadi, o'qitadi — u tayanchimiz.","o":["🏛️ Tayanch","🧳 Mehmon","🚶 Begona","💂 Qo'riqchi"]}},{"t":"mc","q":"Boshqa bolalarning ota-onasini so'ksa nima bo'ladi?","a":3,"e":"O'z ota-onamizni hurmat qilsak, birovning ota-onasini ham hurmat qilamiz.","p":251,"k":"Aks holda o'sha yomon bolalar ham sening ota-onangni so'kadilar.","l":2,"o":["Do'st bo'lib qoladi","Hech narsa bo'lmaydi","Maqtov oladi","Ular ham ota-onangni so'kadi"],"s":{"q":"Birovning ota-onasini so'ksang-chi?","e":"Birovning ota-onasini ham hurmat qilamiz.","o":["🤝 Do'st bo'lasan","🙂 Hech narsa","🏅 Maqtov olasan","😠 Seniki so'kiladi"]}},{"t":"mc","q":"\"Boyish yo'lini topgan bola\" nima qildi?","a":1,"e":"Bola oila uchun qilgan har bir ishiga haq so'radi. Onaning javobi esa mehr pul bilan o'lchanmasligini ko'rsatdi.","p":255,"k":"Bir varaqqa oy davomida bajargan ishlarini yozib narx qo'ydi.","l":1,"o":["Do'kon ochdi","Uy ishlariga narx yozdi","Kitoblarini sotdi","Onasiga sovg'a oldi"],"s":{"q":"\"Boyimoqchi\" bo'lgan bola nima qildi?","e":"Onaning mehri pul bilan o'lchanmaydi.","o":["🏪 Do'kon ochdi","📝 Ishga narx yozdi","📚 Kitob sotdi","🎁 Sovg'a oldi"]}},{"t":"mc","q":"Qiyin holatga tushgan bola nima qilishi kerak?","a":1,"e":"Rostini aytsak, ota-ona aqli va tajribasi bilan chiqish yo'lini ko'rsatadi.","p":255,"k":"bolalar qiyin holatga tushganlarida rostini aytib, ota-onalarini bundan xabardor qilsalar","l":2,"o":["Hammadan yashirishi","Rostini aytib xabar berishi","Yolg'on gapirishi","Indamay yurishi"],"s":{"q":"Qiyin holatga tushsang nima qilasan?","e":"Rostini aytsak, ota-ona yo'l ko'rsatadi.","o":["🙈 Yashiraman","🗣️ Rostini aytaman","🤥 Yolg'on aytaman","😶 Indamayman"]}},{"t":"tf","q":"Ota-ona biror ish buyursa, \"uf\" desa bo'ladi.","a":false,"e":"\"Uf\" so'zi \"sendan bezorman\" degani, uni ota-ona oldida zinhor aytmaslik kerak.","p":251,"k":"Ular biron ish buyurganlarida zinhor “uf ”, dema.","l":1,"s":{"q":"Ota-ona ish buyursa, \"uf\" desa bo'ladi.","e":"\"Uf\" — \"bezorman\" degani, uni aytmaymiz."}},{"t":"tf","q":"Ota-onaning kambag'alligi ayb emas, farzandning odobsizligi esa katta ayb.","a":true,"e":"Odobli bolaning ota-onasi kambag'al bo'lsa ham bolasi tufayli hurmatli bo'ladi.","p":253,"k":"ota-onaning kambag'alligi ayb emas. Aslida farzandning odobsizligi nihoyatda katta aybdir.","l":2,"s":{"q":"Kambag'allik ayb emas, odobsizlik katta ayb.","e":"Odobli bola ota-onasini hurmatli qiladi."}},{"t":"tf","q":"Ertalab turganda va kechqurun yotishdan oldin ota-onaga salom beriladi.","a":true,"e":"Salom ota-onaga hurmat va mehr ko'rsatishning oddiy, ammo go'zal yo'li.","p":251,"k":"Ertalab turganingda va kechqurun yotishingdan oldin, ularni ko'rganingda salom ber.","l":1,"s":{"q":"Ertalab va kechqurun ota-onaga salom beramiz.","e":"Salom — ota-onaga mehr ko'rsatish."}},{"t":"tf","q":"Hikoyada ona ham o'z mehnati uchun boladan pul so'radi.","a":false,"e":"Ona pulni qaytarib berdi va uning haqqi faqat farzandining sevgisi ekanini yozdi.","p":255,"k":"faqat sevging va yonog'ingdan olganim birgina o'pichdir","l":2,"s":{"q":"Hikoyada ona ham boladan pul so'radi.","e":"Ona faqat farzandining sevgisini so'radi."}},{"t":"tf","q":"Ota-onasining so'ziga ishonmay, o'zini aqlli sanagan bola hayotda oson yashaydi.","a":false,"e":"Kitobga ko'ra bunday bolalar hayotda qiynalib, ko'p qiyinchiliklarga duch keladi.","p":255,"k":"ulardan o'zini aqlli va ishbilarmon hisoblagan bolalar hayotda qiynalib qoladi","l":2,"s":{"q":"Ota-onani tinglamagan bola oson yashaydi.","e":"Bunday bola hayotda qiynalib qoladi."}}],"cards":[{"t":"Ota-onasini hurmat qilgan kishining umri uzun bo'ladi","p":252},{"t":"O'g'il dono bo'lsa, ota rohat topibdi.","p":252},{"t":"Ota-onang o'rnini hech kim bosolmaydi.","p":253}],"story":[{"e":"🤱","t":"Ona bizni to'qqiz oy ko'tarib, tunlari parvarish qilgan.","p":250},{"e":"👨","t":"Ota mehnat qilib bizni boqadi — u bizga tayanch.","p":250},{"e":"🙋","t":"Ota-ona chaqirsa \"labbay\" deymiz, \"uf\" demaymiz.","p":251},{"e":"🗣️","t":"Qiyin holatda rostini aytib, ota-onaga aytamiz.","p":255}]},{"id":9,"title":"Hurmat va chiroyli muomala","icon":"🤝","pages":[256,263],"lesson":[{"t":"Aka-uka va opa-singillar eng yaqin qarindoshdir: o'z jigaring yaxshi kunda ham, yomon kunda ham seni tashlab ketmaydi.","p":256},{"t":"Yoshi kattalarni hurmat qilish va kichiklarga mehribon bo'lish go'zal axloqlardan biridir.","p":256},{"t":"Kichik ukalar va singillar bilan holva va o'yinchoqlarni baham ko'r, ularni qo'rqitma, darslariga yordam ber.","p":257},{"t":"Ustozni hurmat qil: u o'qish, yozish va fikrlashga o'rgatadi.","p":259},{"t":"Inson qadri boylik yoki chiroy bilan emas, e'tiqod, odob-axloq va ilm bilan o'lchanadi.","p":262},{"t":"Chiroyli muomala — sabr, odob va yumshoqlik. Yomonlikni yaxshilik bilan daf qil.","p":263}],"qs":[{"t":"mc","q":"Avtobusda tik turishga qiynalayotgan kishini ko'rsangiz nima qilish kerak?","a":0,"e":"Kitobda ojiz kishini ko'rsang, o'rningdan turib unga joy ber, deyilgan. Bu kattalarni hurmat qilishdir.","p":256,"k":"ko'rsang, sendan darajasi past bo'lsa ham o'rningdan turib unga joy ber","l":1,"o":["O'rnidan turib joy berish","Derazaga qarab o'tiraverish","Uni ko'rmaganga olish","Yonidagi joyni ham egallash"],"s":{"q":"Avtobusda qiynalib turgan odamni ko'rsang?","e":"O'rningdan turib, unga joy ber.","o":["🪑 Joy beraman","🪟 Derazaga qarayman","🙈 Ko'rmaganga olaman","💺 Ikki joy olaman"]}},{"t":"tf","q":"Tanish yoshi ulug' kishini uchratsangiz, birinchi bo'lib salom berish kerak.","a":true,"e":"To'g'ri! Kichikning kattaga hurmati birinchi bo'lib salom berishdan boshlanadi.","p":256,"k":"Sen taniydigan yoshi ulug' kishilarni uchratib qolsang, birinchi bo'lib salom ber","l":1,"s":{"q":"Tanish kattaga birinchi bo'lib salom beramiz.","e":"Kichik kattaga birinchi salom beradi."}},{"t":"mc","q":"Hikoyadagi Ismoil singlisini qanday xursand qildi?","a":2,"e":"Ismoil singlisini qo'g'irchog'i bilan aravaga o'tqazib, bog'da sayr qildirdi. Mehribon aka shunday bo'ladi.","p":257,"k":"singlisi qo'g'irchog'i bilan kichkina aravaga o'tirib, undan bog'da sayr qildirishni so'radi","l":1,"o":["Unga qo'g'irchoq sotib oldi","Unga ertak o'qib berdi","Aravada bog'da sayr qildirdi","Uni maktabga olib bordi"],"s":{"q":"Ismoil singlisini qanday xursand qildi?","e":"U singlisini aravada bog'da sayr qildirdi.","o":["🧸 Qo'g'irchoq oldi","📖 Ertak o'qidi","🛒 Aravada aylantirdi","🏫 Maktabga eltdi"]}},{"t":"tf","q":"Kichik ukalarni qo'rqinchli hikoyalar bilan qo'rqitish — shunchaki zararsiz hazil.","a":false,"e":"Noto'g'ri. Kitobda kichik ukalarni qo'rqinchli va bo'lmag'ur hikoyalar bilan qo'rqitma, deyilgan.","p":257,"k":"Kichkina ukalaringni qo'rqinchli va bo'lmag'ur hikoyalar bilan qo'rqitma.","l":1,"s":{"q":"Ukalarni qo'rqinchli gaplar bilan qo'rqitsa bo'ladi.","e":"Yo'q, kichiklarni qo'rqitma."}},{"t":"mc","q":"Ismoilning onasi singlini xursand qilish haqida nima dedi?","a":3,"e":"Onasi: singlingni xursand qilishing juda yaxshi, bu akaning vazifasidir, dedi.","p":257,"k":"singling xursand bo'ladigan ishni qilishing juda yaxshi. Bu akaning vazifasidir","l":2,"o":["Bu kattalarning ishi emas","Bu vaqtni behuda o'tkazish","Faqat bayramda shunday qil","Bu akaning vazifasidir"],"s":{"q":"Onasi Ismoilga nima dedi?","e":"Singlini xursand qilish akaning vazifasi.","o":["🙅 Kattalar ishi emas","⏳ Vaqt behuda ketdi","🎉 Faqat bayramda qil","👦 Akaning vazifasi"]}},{"t":"mc","q":"«Baxil savdogar» hikoyasida etikdo'z Vali topgan hamyonni nima qildi?","a":1,"e":"Halol etikdo'z hamyonni egasiga topshirdi. Yolg'on gapirgan baxil savdogar esa oxirida afsuslandi.","p":258,"k":"savdogarning oldiga borib unga hamyonni topshirdi","l":2,"o":["O'zi ishlatib yubordi","Egasiga qaytarib berdi","Bozorda tashlab ketdi","Yarmini olib qoldi"],"s":{"q":"Halol etikdo'z topgan hamyonni nima qildi?","e":"Topilgan narsani egasiga qaytaramiz.","o":["💸 O'zi ishlatdi","🤲 Egasiga qaytardi","🚶 Tashlab ketdi","🌗 Yarmini oldi"]}},{"t":"tf","q":"Ba'zi kitoblarda ustozning haqqi ota-ona haqqidan keyin turishi aytilgan.","a":true,"e":"To'g'ri. Ota-ona dunyoga kelishimizga sababchi bo'lsa, ustoz oq-qorani tanitadi.","p":259,"k":"Ba'zi kitoblarda ustozning haqqi ota-ona haqqidan keyin turishi aytilgan.","l":2,"s":{"q":"Kitobda: ustoz haqqi ota-ona haqqidan keyin turadi.","e":"Ustoz bizga oq-qorani tanitadi."}},{"t":"mc","q":"Ustoz oldidagi qaysi odob kitobda aytilgan?","a":2,"e":"Ustoz mehrini qozonish uchun uning o'rniga o'tirmaslik va oldida ruxsatsiz gapirmaslik kerak.","p":259,"k":"Ustozing o'rniga o'tirma. 3. Ustozing oldida ruxsatsiz gapirma.","l":1,"o":["Ustoz o'rniga o'tirish","Ustozdan oldinda yurish","Ruxsatsiz gapirmaslik","Darsga kechikib kelish"],"s":{"q":"Ustoz oldida qanday odob bor?","e":"Ustoz oldida ruxsatsiz gapirmaymiz.","o":["🪑 O'rniga o'tir","🚶 Undan oldin yur","🤐 Ruxsatsiz gapirma","⏰ Darsga kechik"]}},{"t":"mc","q":"Imom Buxoriy ustozidan kelgan maktubni qanday oldi?","a":0,"e":"Imom Buxoriy maktubni ikki qo'llab olib, ehtirom bilan o'qidi. Ustoz uzoqda bo'lsa ham hurmat qilinadi.","p":260,"k":"Keyin maktubni ikki qo'llab olib, ehtirom bilan xatni o'qiydi.","l":2,"o":["Ikki qo'llab, ehtirom bilan","Bir qo'llab, shoshilib","Ochmasdan qo'yib qo'ydi","Boshqaga o'qitib berdi"],"s":{"q":"Imom Buxoriy ustoz xatini qanday oldi?","e":"Ustozni uzoqda bo'lsa ham hurmat qilamiz.","o":["🙌 Ikki qo'llab","✋ Bir qo'llab","📪 Ochmay qo'ydi","👤 Boshqaga o'qitdi"]}},{"t":"tf","q":"Do'stlarga laqab to'qish ularning diliga ozor yetkazadi.","a":true,"e":"To'g'ri. Hech kimni u yomon ko'radigan laqab bilan chaqirmaslik kerak.","p":261,"k":"Do'stlaring va tengdoshlaringga laqablar to'qima. Chunki bu ularning diliga ozor etkazadi.","l":1,"s":{"q":"Do'stga laqab qo'yish uning dilini og'ritadi.","e":"Hech kimni yomon laqab bilan chaqirma."}},{"t":"tf","q":"Inson qadri birinchi navbatda uning boyligi va chiroyi bilan o'lchanadi.","a":false,"e":"Noto'g'ri. Inson qadri e'tiqodi, odob-axloqi va ilmi bilan belgilanadi; chiroy yosh o'tgan sari o'zgaradi.","p":262,"k":"Inson qadri yana tashqi ko'rinish, chiroyga qarab belgilanmaydi.","l":2,"s":{"q":"Odamning qadri boylik va chiroyda.","e":"Yo'q, qadr odob, ilm va e'tiqodda."}},{"t":"mc","q":"Kitobga ko'ra, yomonlikni nima bilan daf qilish kerak?","a":3,"e":"Yomonlikka yaxshilik bilan javob berilsa, dushman ham do'stga aylanadi.","p":263,"k":"Sen yomonlikni yaxshilik bilan daf qil. Chunki bu narsa dushmaningni do'stga aylantiradi.","l":2,"o":["Jahl bilan","Yomonlik bilan","Arazlab ketish bilan","Yaxshilik bilan"],"s":{"q":"Yomonlikka nima bilan javob beramiz?","e":"Yaxshilik dushmanni ham do'st qiladi.","o":["😠 Jahl bilan","👊 Yomonlik bilan","😤 Arazlab","💛 Yaxshilik bilan"]}}],"cards":[{"t":"Ustoz abadiy tirikligimning sababchisi, otam esa o'tkinchi hayotimning sababchisidir!","p":260},{"t":"Sizlarning menga eng suyuklirog'ingiz eng axloqi go'zalrog'ingizdir","p":263},{"t":"Agar yaxshi gaping bo'lmasa, tilingni bo'hton va g'iybat bilan bulg'ama.","p":263}],"story":[{"e":"🤝","t":"Kattalarni hurmat qil, kichiklarga mehribon bo'l.","p":256},{"e":"🧸","t":"Ukang va singlingni qo'rqitma, ularga yordam ber.","p":257},{"e":"📚","t":"Ustozni hurmat qil: u o'qish va yozishni o'rgatadi.","p":259},{"e":"💛","t":"Yomonlikka yaxshilik bilan javob ber.","p":263}]},{"id":10,"title":"Mehmon, ziyorat va do'stlik","icon":"🏡","pages":[264,272],"lesson":[{"t":"Luqmoni hakim to'g'ri so'zlash, yaxshilik, omonatdorlik va kamtarlik tufayli cho'pondan hakimga aylandi.","p":264},{"t":"Ziyoratga munosib vaqtda bor, uyga kirishdan oldin ruxsat so'ra va uzoq o'tirma.","p":265},{"t":"Mehmonni ochiq chehra bilan kutib ol, ota-onangga yordamlash, dasturxonga ruxsatsiz qo'l uzatma.","p":267},{"t":"Boshqa uyga, hatto ota-onang oldiga kirishdan oldin ham ruxsat so'ra.","p":268},{"t":"Keksa, kasal va ojiz kishilarga yordam ber, uy hayvonlarini qiynama.","p":269},{"t":"Yaxshi va odobli bolalarni do'st tut. Do'stning qandayligi qiyin vaqtda bilinadi.","p":271}],"qs":[{"t":"mc","q":"Luqmoni hakim hakim bo'lishidan oldin kim bo'lgan?","a":1,"e":"Luqmon: «Ha, o'sha cho'ponman», dedi. U yaxshi xulqi tufayli hakim darajasiga yetdi.","p":264,"k":"Ha, o'sha cho'ponman, – deb javob berdi Luqmon","l":1,"o":["Savdogar","Cho'pon","Podshoh","Etikdo'z"],"s":{"q":"Luqmon hakim bo'lishidan oldin kim edi?","e":"U cho'pon edi, yaxshi xulqi bilan hakim bo'ldi.","o":["💰 Savdogar","🐑 Cho'pon","👑 Podshoh","👞 Etikdo'z"]}},{"t":"tf","q":"Luqmoni hakim behuda gapirmaslik va o'zini kamtar tutish tufayli yuksak darajaga erishgan.","a":true,"e":"To'g'ri. U to'g'ri so'zlash, behuda gapirmaslik va kamtarlik tufayli hakim bo'ldi.","p":264,"k":"behuda gapirmaslik, musibat va qiyinchiliklarga mardona chidash va o'zini kamtar tutish tufayli","l":2,"s":{"q":"Luqmon kam gapirib, kamtar bo'lib hakim bo'ldi.","e":"Kamtarlik va to'g'ri so'z insonni yuksaltiradi."}},{"t":"mc","q":"Ziyoratga qaysi vaqtda borish noqulay?","a":0,"e":"Ziyorat uchun munosib vaqt tanlash kerak: bu uxlash yoki ovqatlanish vaqti bo'lmasin.","p":264,"k":"Bu uxlash, ovqatlanish yoki boshqa ish bilan mashg'ul bo'linadigan vaqt bo'lmasin.","l":1,"o":["Uxlash yoki ovqat vaqtida","Oldindan kelishilgan vaqtda","Bayram kunlarida","Safardan qaytganda"],"s":{"q":"Mehmonga qachon borish noqulay?","e":"Uyqu va ovqat vaqtida mehmonga bormaymiz.","o":["😴 Uyqu, ovqat payti","📅 Kelishilgan vaqt","🎉 Bayram kuni","🧳 Safardan keyin"]}},{"t":"tf","q":"Kasalni ko'rgani borganda uzoq o'tirib, ko'p gapirish kerak.","a":false,"e":"Noto'g'ri. Bemor oldida uzoq o'tirmaslik va uni xursand qiladigan so'zlarni gapirish kerak.","p":265,"k":"Kasal ko'rishga borganingda ham uzoq o'tirma yoki ko'p gapirib uni qiynab qo'yma.","l":1,"s":{"q":"Kasal oldida uzoq o'tirib, ko'p gapiramiz.","e":"Bemor oldida uzoq o'tirmaymiz."}},{"t":"mc","q":"Mehmonga borganda oldingizga qo'yilgan ovqat haqida kitobda nima deyilgan?","a":3,"e":"Ziyorat odobiga ko'ra, oldingga qo'yilgan ovqatni yomonlama, foydali so'zlar bilan cheklan.","p":265,"k":"Foydali so'zlar bilan cheklan. 8. Oldingga qo'yilgan ovqatni yomonlama.","l":2,"o":["Kamchiligini aytish kerak","Faqat yoqqanini yeyish","Boshqa taom so'rash","Uni yomonlamaslik kerak"],"s":{"q":"Mehmonda ovqat haqida nima deyilgan?","e":"Oldingga qo'yilgan ovqatni yomonlama.","o":["👎 Kamchilik ayt","😋 Yoqqanini ye","🍲 Boshqasini so'ra","🙂 Yomonlama"]}},{"t":"mc","q":"Cho'pon Ahmad tog'aning yaxshiligi nimaga sabab bo'ldi?","a":2,"e":"U kasal yigitga chakmonini berdi va shu chakmon tufayli o'g'li topildi. Yaxshilik albatta qaytadi.","p":267,"k":"cho'pon Ahmad tog'aning yaxshiligi o'g'lining topilishiga sabab bo'ldi.","l":2,"o":["Boy bo'lib ketishiga","Shaharga ko'chishiga","O'g'lining topilishiga","Ko'p qo'y olishiga"],"s":{"q":"Ahmad tog'aning yaxshiligi nima berdi?","e":"Yaxshilik albatta qaytadi.","o":["💰 Boy bo'ldi","🏢 Shaharga ko'chdi","👦 O'g'li topildi","🐑 Ko'p qo'y oldi"]}},{"t":"tf","q":"Mehmonni ochiq yuz bilan kutib olish katta ziyofat bilan barobar.","a":true,"e":"To'g'ri. Mehmonni «xush kelibsiz» deb, ochiq chehra bilan kutib olish kerak.","p":267,"k":"Mehmonni ochiq yuz bilan kutib olish katta ziyofat bilan barobardir.","l":1,"s":{"q":"Mehmonni ochiq yuz bilan kutish katta ziyofatdek.","e":"Mehmonga «Xush kelibsiz!» deymiz."}},{"t":"mc","q":"Uyga mehmon kelganda odobli bola nima qiladi?","a":1,"e":"Odobli bola mehmon kutishda ota-onasiga ko'maklashadi va dasturxonga ruxsatsiz qo'l uzatmaydi.","p":267,"k":"agar uyimizga mehmon kelsa, ota-onamizga yordamlashishimiz, mehmon kutishga ko'maklashib yuborishimiz kerak","l":1,"o":["Dasturxondan qand oladi","Ota-onasiga yordamlashadi","Kattalar gapiga quloq soladi","Baland ovozda o'ynaydi"],"s":{"q":"Mehmon kelsa, odobli bola nima qiladi?","e":"Mehmon kutishda ota-onaga yordam beramiz.","o":["🍬 Qand oladi","🤲 Ota-onaga yordam","👂 Gapga quloq soladi","📢 Baland o'ynaydi"]}},{"t":"mc","q":"Imom A'zam (Abu Hanifa) uyini nega baland qurdirgan edi?","a":0,"e":"Kufaga kelgan kambag'allar uni ko'rib, to'g'ri uning uyiga mehmon bo'lishi uchun baland qurdirgan.","p":268,"k":"Kufaga kelgan kambag'allar birinchi mening uyimga ko'zlari tushib","l":2,"o":["Kambag'allar mehmon bo'lishi uchun","Boyligini ko'rsatish uchun","Shahar chiroyli bo'lishi uchun","Ko'p xona bo'lishi uchun"],"s":{"q":"Abu Hanifa uyini nega baland qurdirdi?","e":"Kambag'allar ko'rib, mehmon bo'lishi uchun.","o":["🍞 Kambag'allar uchun","💎 Boylik ko'rsatish","🌆 Shahar chiroyi","🚪 Ko'p xona uchun"]}},{"t":"tf","q":"Ota-ona o'z xonasida bo'lsa, ularning oldiga ruxsat so'ramay kiraverish mumkin.","a":false,"e":"Noto'g'ri. «Kirsam maylimi?» deb ruxsat so'rash kerak; ruxsatsiz kirish odobli bolaga yarashmaydi.","p":268,"k":"Ruxsat olmasdan to'g'ridan-to'g'ri oldilariga kirib borish odobli bolaga yarashmaydi.","l":2,"s":{"q":"Ota-ona xonasiga ruxsatsiz kirsa bo'ladi.","e":"«Kirsam maylimi?» deb so'raymiz."}},{"t":"tf","q":"«Sadoqatli xizmatkor» hikoyasidagi boy keksa xizmatkorini haydab yubormadi.","a":true,"e":"To'g'ri. Boy uzoq yil sadoqat bilan xizmat qilgan odamni kuchdan qolganda haydash odamgarchilik emas, dedi.","p":270,"k":"Mana endi quvvati ketib, kuchdan qolganida uni haydab yuborish odamgarchilikdan emas.","l":2,"s":{"q":"Boy keksa xizmatkorini haydab yubormadi.","e":"Keksa odamni haydash odamgarchilik emas."}},{"t":"mc","q":"Kitobga ko'ra, do'stning qandayligi qachon bilinadi?","a":2,"e":"Haqiqiy do'st faqat xursand kunlarda emas, qiyin vaqtlarda ham yoningda bo'ladi.","p":271,"k":"Do'stning qandayligi qiyin va og'ir vaqtlarda bilinadi.","l":1,"o":["Faqat bayramlarda","Sovg'a berganda","Qiyin va og'ir vaqtlarda","O'yin paytida"],"s":{"q":"Do'st qachon bilinadi?","e":"Haqiqiy do'st qiyin kunda yoningda bo'ladi.","o":["🎉 Bayramda","🎁 Sovg'a berganda","😣 Qiyin vaqtda","⚽ O'yinda"]}}],"cards":[{"t":"Yaxshilik yo'lida chekilgan mehnat erda qolmaydi.","p":264},{"t":"Har narsaning yangisi, ammo do'stning eskisi yaxshi.","p":272},{"t":"Soxta do'st – ochiq dushmandan yomon.","p":272}],"story":[{"e":"🐑","t":"Luqmon cho'pon edi, yaxshi xulqi bilan hakim bo'ldi.","p":264},{"e":"🚪","t":"Birovning uyiga kirishdan oldin ruxsat so'ra.","p":268},{"e":"😊","t":"Mehmonni ochiq yuz bilan kutib ol.","p":267},{"e":"🤝","t":"Do'st qiyin kunda bilinadi.","p":271}]},{"id":11,"title":"Shafqat va salom odobi","icon":"🐾","pages":[273,279],"lesson":[{"t":"Davlat mulki — barchaning mulki. Maktabdagi parta va darsliklarni avaylab-asra.","p":273},{"t":"Hayvonlar ham his qiladi, urilsa joni og'riydi, lekin buni gapira olmaydi. Ularga mehribon bo'l.","p":274},{"t":"Hayvonga yetarli ozuqa va dam ber, toqatidan ortiq ish yuklama, kasal bo'lsa davolat.","p":275},{"t":"Navoiy bobomiz kichkina chumolini ham ozor topmasin deb iniga qaytarib qo'ygan.","p":276},{"t":"Salom — tinchlik va yaxshilik tilash. Salomni to'liq va to'g'ri berish kerak.","p":278},{"t":"Odobli bola tabassumli bo'ladi, birinchi bo'lib salom beradi va kasallarni borib ko'radi.","p":279}],"qs":[{"t":"tf","q":"Hayvonlar ham his qiladi: agar urilsa, joni og'riydi.","a":true,"e":"To'g'ri. Hayvonlar og'riqni sezadi, lekin gapira olmaydi. Shuning uchun ularga muloyim bo'lish kerak.","p":274,"k":"Chunki ular ham his qiladi, agar urilsa, joni og'riydi.","l":1,"s":{"q":"Hayvonni ursa, uning joni og'riydi.","e":"Hayvonlarga muloyim bo'lamiz."}},{"t":"mc","q":"Hadisdagi odam chanqagan itga nima qildi?","a":3,"e":"U quduqqa tushib, mahsisiga suv to'ldirib itga ichirdi va Alloh undan rozi bo'ldi.","p":274,"k":"quduqqa tushib, mahsisiga suv to'ldirib itga ichiribdi","l":1,"o":["Uni haydab yubordi","Ko'rmay o'tib ketdi","Unga tosh otdi","Mahsisida suv olib ichirdi"],"s":{"q":"Hadisdagi odam chanqagan itga nima qildi?","e":"U itga suv berdi, Alloh undan rozi bo'ldi.","o":["🏃 Haydab yubordi","🙈 Ko'rmay o'tdi","🪨 Tosh otdi","💧 Suv ichirdi"]}},{"t":"tf","q":"Qushlarning uyasini buzish va polaponini olish zararsiz o'yin.","a":false,"e":"Noto'g'ri. Kitobda qushlar uyasini buzish va onasini chirqillatish yaxshi emas, deyilgan.","p":274,"k":"Qushlarning uyasini buzish, polaponini olib qo'yib, onasini chirqillatish ham yaxshi emas.","l":2,"s":{"q":"Qush uyasini buzish zararsiz o'yin.","e":"Yo'q, qush uyasini buzish yaxshi emas."}},{"t":"mc","q":"Qaysi biri jonzotlarga muloyimlik qilish jumlasidan?","a":1,"e":"Hayvonga yetarli ozuqa va dam berish, kasal bo'lsa davolatish — unga muloyimlik qilishdir.","p":275,"k":"Etarli miqdorda dam berish va kasal bo'lsa davolatish.","l":2,"o":["Ko'p yuk ortib ishlatish","Yetarli dam berish","Bolasidan ajratib olish","Ermak uchun quvlash"],"s":{"q":"Hayvonga qaysi biri muloyimlik?","e":"Hayvonga ozuqa va dam beramiz.","o":["📦 Ko'p yuk ortish","😌 Dam berish","💔 Bolasini olish","🏃 Ermakka quvlash"]}},{"t":"mc","q":"Mushukni ermak uchun urgan bola bilan oxiri nima bo'ldi?","a":2,"e":"Mushuk o'zini himoya qilib, bolaning yuzini tirnadi. Hayvonga ozor berish yomon oqibatga olib keladi.","p":275,"k":"Mushukning joni og'rib, butun kuchini to'plab, bolaning o'ziga chang soldi","l":1,"o":["Mushuk u bilan do'stlashdi","Onasi unga sovg'a berdi","Mushuk uning yuzini tirnadi","Hech narsa bo'lmadi"],"s":{"q":"Mushukni urgan bola bilan nima bo'ldi?","e":"Hayvonga ozor bersang, o'zingga yomon.","o":["🤝 Do'stlashdi","🎁 Sovg'a oldi","😿 Mushuk tirnadi","🤷 Hech narsa"]}},{"t":"mc","q":"Navoiy bobomiz nega namozdan keyin shoshib ketdi?","a":0,"e":"Elkasiga chumoli ilashib qolgan edi. Navoiy uni ozor topmasin deb iniga olib borib qo'ydi.","p":276,"k":"tahorat olgan joyga borib, uni ini oldiga qo'ydim","l":2,"o":["Chumolini iniga qaytarish uchun","Bog'ida mehmon kutgani uchun","Kasal bo'lib qolgani uchun","Kitob yozishga shoshgani uchun"],"s":{"q":"Navoiy namozdan keyin nega shoshdi?","e":"U chumolini iniga olib borib qo'ydi.","o":["🐜 Chumoli uchun","🏡 Mehmon kutish","🤒 Kasal bo'ldi","📖 Kitob yozish"]}},{"t":"tf","q":"Mehribon Hasan och itga nonidan bir bo'lak berdi.","a":true,"e":"To'g'ri. Hasan itga achinib, nonni maydalab berdi. Uyiga kelsa, savatidagi non kamaymagan edi.","p":276,"k":"bir bo'lak nonni olib maydalab it oldiga tashladi","l":1,"s":{"q":"Hasan och itga nonidan bir bo'lak berdi.","e":"Hasanning savatidagi non kamaymadi."}},{"t":"mc","q":"Hasan hikoyasi oxiridagi hadisda nima deyilgan?","a":3,"e":"Hadisda kishining molu dunyosi qilingan sadaqadan kamaymaydi, deyilgan.","p":276,"k":"Kishining molu dunyosi qilingan sadaqadan kamaymaydi","l":2,"o":["Nonni tejash kerak","Faqat boylar sadaqa beradi","Itga yaqinlashma","Sadaqadan mol kamaymaydi"],"s":{"q":"Hasan hikoyasidagi hadisda nima deyilgan?","e":"Sadaqadan mol kamaymaydi.","o":["🍞 Nonni teja","💰 Boylar beradi","🐕 Itga yaqinlashma","🤲 Sadaqadan kamaymas"]}},{"t":"mc","q":"Kim kimga salom berishi odobdan?","a":1,"e":"Kichik kattaga, turgan o'tirganga, ulovdagi piyodaga salom berishi odobdandir.","p":278,"k":"Kichik kattaga, turgan o'tirganga va ulovda ketayotgan piyoda odamga salom berishi odobdandir.","l":1,"o":["Katta kichikka","Kichik kattaga","O'tirgan turganga","Piyoda ulovdagiga"],"s":{"q":"Kim kimga salom beradi?","e":"Kichik kattaga birinchi salom beradi.","o":["👴 Katta kichikka","👦 Kichik kattaga","🪑 O'tirgan turganga","🚶 Piyoda ulovdagiga"]}},{"t":"tf","q":"Ovqat yeyayotgan odamga albatta salom berish kerak.","a":false,"e":"Noto'g'ri. Ovqat yeyayotgan yoki biror ish bilan band odamga salom berilmaydi.","p":278,"k":"Ovqat eyayotgan va shu kabi biron ish bilan mashg'ul bo'lgan odamlarga salom berma.","l":2,"s":{"q":"Ovqat yeyayotganga albatta salom beramiz.","e":"Ovqat yeyayotgan odamga salom berilmaydi."}},{"t":"mc","q":"Kitobga ko'ra, salomni qanday berish kerak?","a":0,"e":"«Assalomu alaykum» — «sizga tinchlik va salomatlik tilayman» degani. Shuning uchun salom to'liq aytiladi.","p":278,"k":"Demak, salomni to'liq va to'g'ri berishimiz kerak.","l":2,"o":["To'liq va to'g'ri","Chala va tez","Faqat «assalom» deb","Faqat bosh irg'ab"],"s":{"q":"Salomni qanday beramiz?","e":"«Assalomu alaykum» deb to'liq aytamiz.","o":["✅ To'liq va to'g'ri","⚡ Chala va tez","💬 Faqat «assalom»","🙂 Faqat bosh irg'ab"]}},{"t":"tf","q":"«Haqiqiy do'stlik» hikoyasidagi Ahmad do'stlariga birinchi bo'lib salom berardi.","a":true,"e":"To'g'ri. Ahmad tabassumli edi, birinchi salom berardi — shuning uchun hamma uni yaxshi ko'rardi.","p":279,"k":"do'stlari bilan chiroyli odob bilan ko'rishadi, birinchi bo'lib ularga salom beradi","l":1,"s":{"q":"Ahmad do'stlariga birinchi salom berardi.","e":"Shuning uchun hamma uni yaxshi ko'rardi."}}],"cards":[{"t":"Salom berish odam uchun omonlik demakdir.","p":279},{"t":"Agar senga birov salom bersa, unga undan ham go'zalroq yoki o'shanga o'xshatib javob ber.","p":278},{"t":"Kishining molu dunyosi qilingan sadaqadan kamaymaydi","p":276}],"story":[{"e":"🐾","t":"Hayvonlarning ham joni og'riydi, ularni urma.","p":274},{"e":"🐜","t":"Navoiy chumolini ham iniga qaytarib qo'ygan.","p":276},{"e":"👋","t":"Salom — tinchlik tilash, uni to'liq ber.","p":278},{"e":"😊","t":"Kichik kattaga birinchi bo'lib salom beradi.","p":278}]},{"id":12,"title":"So'z odobi va tilni tiyish","icon":"💬","pages":[279,292],"lesson":[{"t":"O'rtacha ovozda, shoshilmay gapir va suhbatdoshingning so'zini bo'lma.","p":280},{"t":"Insonga bir og'iz va ikki quloq berilgan: kam gapirib, ko'p eshitish kerak.","p":282},{"t":"Jamoat joylarida baland gapirish, atrof tozaligiga beparvolik va o'zini maqtash odobsizlikdir.","p":284},{"t":"Do'stlaringning sirini saqla, g'iybat va chaqimchilikdan uzoq bo'l.","p":288},{"t":"Maqtanchoq bo'lma: «kamtarga kamol, manmanga zavol».","p":290},{"t":"O'yinda yomon so'z aytma, o'rtog'ingga ozor berma, ovqatdan keyin darhol o'ynama.","p":292}],"qs":[{"t":"mc","q":"Biror odam bilan qanday ovozda gaplashish kerak?","a":3,"e":"Suhbatdosh ranjimasligi uchun ovozni juda baland ham, juda past ham qilmaslik kerak.","p":280,"k":"Agar bir odamga gapirsang, o'rtacha ovoz bilan gapir","l":1,"o":["Juda baland ovozda","Shivirlab, juda past","Qichqirib","O'rtacha ovozda"],"s":{"q":"Odam bilan qanday ovozda gaplashamiz?","e":"Juda baland ham, juda past ham emas.","o":["📢 Juda baland","🤫 Juda past","😱 Qichqirib","🙂 O'rtacha ovozda"]}},{"t":"tf","q":"Kimdir siz biladigan hikoyani aytsa, «bilaman» deb uning so'zini bo'lish kerak.","a":false,"e":"Noto'g'ri. Bilsangiz ham sabr bilan tinglang, aytayotgan odamni xijolat qilmang.","p":280,"k":"uni hijolat qilma. Bilsang ham sabr bilan tingla.","l":2,"s":{"q":"Hikoyani bilsang, «bilaman» deb so'zni bo'l.","e":"Bilsang ham sabr bilan tingla."}},{"t":"mc","q":"Hakimlarga ko'ra, nega insonga bir og'iz va ikki quloq berilgan?","a":2,"e":"Inson bir marta gapirib, ko'p marta eshitishi kerak. Eshituvchi ko'p narsa o'rganadi.","p":282,"k":"Shuning uchun u bir marta gapirishi va ko'p marta eshitishi kerak.","l":2,"o":["Ko'p gapirib, kam eshitsin","Faqat qo'shiq aytsin","Kam gapirib, ko'p eshitsin","Hech kimni tinglamasin"],"s":{"q":"Nega bir og'iz va ikki quloq berilgan?","e":"Ko'p eshitgan ko'p narsa o'rganadi.","o":["📣 Ko'p gapirsin","🎤 Qo'shiq aytsin","👂 Ko'proq eshitsin","🙉 Tinglamasin"]}},{"t":"mc","q":"Kitobda maqtanchoqlik haqida nima maslahat berilgan?","a":1,"e":"Zo'r ish qilsang ham kekkayma, o'zingni maqtama — seni boshqalar maqtasin. Kamtarga kamol!","p":290,"k":"sen zinhor maqtanchoq bo'lma, juda zo'r ishlarni qilsang ham kekkayma","l":1,"o":["O'zingni doim maqta","Kekkayma, boshqalar maqtasin","Har kuni yutuqni ko'z-ko'z qil","Faqat do'stlar oldida maqtan"],"s":{"q":"Maqtanish haqida nima deyilgan?","e":"O'zingni maqtama, seni boshqalar maqtasin.","o":["😎 O'zingni maqta","🙇 Kekkayma","🏆 Ko'z-ko'z qil","👫 Do'stga maqtan"]}},{"t":"mc","q":"Vazirning o'g'li «Uzukdan ham chiroylisini ko'rganmisan?» degan savolga nima dedi?","a":0,"e":"Odobli bola «Uzuk taqilgan qo'l uzukdan chiroyli», deb chiroyli javob berdi va podshohni xursand qildi.","p":283,"k":"Uzuk taqilgan qo'l uzukdan chiroyli, – debdi bola.","l":2,"o":["Uzuk taqilgan qo'l chiroyli","Yo'q, hech ko'rmaganman","Otamning uzugi chiroyli","Mening uzugim chiroyli"],"s":{"q":"Vazir o'g'li «Uzukdan chiroylisi bormi?»ga nima dedi?","e":"Chiroyli javob podshohni xursand qildi.","o":["💍 Uzukli qo'l","🤷 Ko'rmaganman","👨 Otamning uzugi","👦 Mening uzugim"]}},{"t":"tf","q":"Jamoat joylarida ovozni baland ko'tarib gapirish odobsizlik sanaladi.","a":true,"e":"To'g'ri. Odamlar ko'p joyda baland gapirish boshqalarni bezovta qiladi.","p":284,"k":"Jamoat joylarda ovozini baland ko'tarib gapirish.","l":1,"s":{"q":"Ko'p odam bor joyda baland gapirish odobsizlik.","e":"Baland gap boshqalarni bezovta qiladi."}},{"t":"mc","q":"Birovning aybi ko'rinsa, kitobga ko'ra qanday yo'l tutiladi?","a":2,"e":"Aybni odamlar oldida ochmasdan, o'zini chetga chaqirib, muloyimlik bilan tushuntirish kerak.","p":284,"k":"uning o'zini chetga chaqirib, muloyimlik bilan xatosi tushuntiriladi","l":2,"o":["Hammaning oldida aytiladi","Boshqalarga tarqatiladi","Chetga chaqirib, muloyim aytiladi","Ustidan kulinadi"],"s":{"q":"Birovning aybini ko'rsang nima qilasan?","e":"Aybni yolg'iz, muloyim qilib aytamiz.","o":["📢 Hammaga aytaman","📨 Tarqataman","🤫 Chetda, muloyim","😂 Ustidan kulaman"]}},{"t":"tf","q":"Birovning sirini ochgan kishi sizning siringizni ham boshqalarga yetkazadi.","a":true,"e":"To'g'ri. Shuning uchun sir saqlay oladigan bolalar bilan do'st tutinish kerak.","p":287,"k":"Birovning sirini ochgan kishi sening siringni ham boshqalarga etkazadi.","l":2,"s":{"q":"Birov sirini ochgan, sening siringni ham ochadi.","e":"Sir saqlaydigan bola bilan do'st bo'l."}},{"t":"mc","q":"Ramziy qoyalardan eshitgan ovoz aslida nima edi?","a":3,"e":"Bu aks-sado edi: Ramziy nima desa, o'shani eshitdi. Kim yomon gapirsa, yomon gap eshitadi.","p":286,"k":"Ramziy aks-sado nima ekanini bilmasdi. Shuning uchun tepalikda bir bola","l":1,"o":["Boshqa bola","Otasining ovozi","Qushning sayrashi","Aks-sado"],"s":{"q":"Ramziy qoyada eshitgan ovoz nima edi?","e":"Yomon gapirsang, yomon gap eshitasan.","o":["👦 Boshqa bola","👨 Otasi","🐦 Qush","🔁 Aks-sado"]}},{"t":"tf","q":"G'iybat ham, tuhmat ham juda yomon odat va katta gunoh.","a":true,"e":"To'g'ri. Birovni yo'qligida yomonlash g'iybat, yolg'ondan ayblash tuhmatdir — ikkisidan ham saqlanish kerak.","p":288,"k":"g'iybat va tuhmat juda yomon odat bo'lib, ikkisi ham katta gunohdir!","l":1,"s":{"q":"G'iybat va tuhmat — yomon odat, katta gunoh.","e":"G'iybat va tuhmatdan saqlanamiz."}},{"t":"mc","q":"Hasan Basriy uni g'iybat qilgan kishiga nima yubordi?","a":1,"e":"Hasan Basriy g'iybatchiga xurmo yubordi. Bu bilan g'iybat qilish g'iybatchining o'ziga zarar ekanini uqtirdi.","p":289,"k":"Hasan darhol g'iybat qilgan kishiga bir idishda xurmo yubordi.","l":2,"o":["Achchiq maktub","Bir idishda xurmo","Qozining chaqiruvi","Hech narsa yubormadi"],"s":{"q":"Hasan Basriy g'iybatchiga nima yubordi?","e":"U g'iybatchiga bir idish xurmo yubordi.","o":["📝 Achchiq xat","🌴 Xurmo","📜 Qozi chaqiruvi","🚫 Hech narsa"]}},{"t":"tf","q":"Ovqat yegandan keyin darhol o'ynash foydali.","a":false,"e":"Noto'g'ri. Ovqatdan so'ng darhol o'ynash oshqozonga zarar qiladi.","p":292,"k":"Ovqat egandan keyin darhol o'ynamasin. Chunki bu narsa oshqozonga zarar qilib","l":1,"s":{"q":"Ovqatdan keyin darhol o'ynash foydali.","e":"Bu oshqozonga zarar qiladi."}}],"cards":[{"t":"Aytilgan so'z otilgan o'qdir, aytilgandan keyin uni qaytarib bo'lmaydi.","p":282},{"t":"Tili shirin odamning do'sti ko'p bo'ladi.","p":281},{"t":"Suvning mazasi muz bilan, oshning mazasi tuz bilan, odam yaxshiligi so'z bilandir.","p":282},{"t":"Siring ichingda ekan, u sening asiringdir, sendan tashqariga chiqsa, sen unga asir bo'lasan.","p":287}],"story":[{"e":"💬","t":"O'rtacha ovozda gapir, birovning so'zini bo'lma.","p":280},{"e":"👂","t":"Bir og'iz, ikki quloq: kam gapir, ko'p eshit.","p":282},{"e":"🤐","t":"Sirni saqla, g'iybat qilma.","p":288},{"e":"🙇","t":"Maqtanchoq bo'lma: kamtarga kamol.","p":290}]},{"id":13,"title":"Vaqt va tejamkorlik","icon":"⏳","pages":[293,307],"lesson":[{"t":"Vaqtni tejash uni foydali ishlarga sarflash demakdir. O'tgan umr hech qachon qaytib kelmaydi.","p":294},{"t":"Yoshlik tez o'tadi. Uni ilm, odob va biron kasb-hunar o'rganishga sarflash kerak.","p":296},{"t":"Tejamkorlik pul sarflashda o'rtamiyona bo'lishdir: isrof ham, baxillik ham xato.","p":298},{"t":"Tejamkorlik baxillik emas, saxiylik esa isrof emas. Bu farqni yaxshi ajratish kerak.","p":301},{"t":"Ovqat yeyish, uxlash, o'ynash — har bir ishda me'yorga rioya qilish lozim.","p":304},{"t":"Televizorni imkon qadar kam ko'rish va ekrandan kamida uch metr uzoqda o'tirish kerak.","p":306}],"qs":[{"t":"mc","q":"Hikoyadagi Ahmad nima uchun katta yutuqlarga erishdi?","a":0,"e":"Ahmad bo'sh vaqtini ham o'qishga sarfladi. Vaqtini zoe ketkazmagani uchun obro'si ko'tarildi.","p":293,"k":"Bu yigit vaqtning qadrini bilib, undan unumli foydalangani","l":1,"o":["Vaqtning qadrini bildi","Otasi boylik qoldirdi","Ko'p o'yin-kulgi qildi","Savdogar bo'lib qoldi"],"s":{"q":"Ahmad nima uchun katta yutuqqa erishdi?","e":"Ahmad bo'sh vaqtini ham o'qishga sarfladi.","o":["⏳ Vaqtni qadrladi","💰 Otasi boy edi","🎮 Ko'p o'ynadi","🛒 Savdogar bo'ldi"]}},{"t":"tf","q":"Kitobga ko'ra, puldan ko'ra ko'proq vaqtni qizg'anish kerak.","a":true,"e":"To'g'ri! Pulni yana topish mumkin, ammo o'tgan umr hech qachon qaytib kelmaydi.","p":294,"k":"Sen puldan ko'ra ko'proq vaqtingni qizg'anishing kerak.","l":2,"s":{"q":"Puldan ko'ra vaqtni ko'proq qizg'anish kerak.","e":"Pul topiladi, o'tgan vaqt qaytmaydi."}},{"t":"mc","q":"Hadisda \"Kasallikdan oldin ... qadriga et\" deyilgan. Nuqtalar o'rnida nima?","a":3,"e":"Hadisda besh narsaning qadriga yetish buyurilgan: kasallikdan oldin sog'liqning qadriga yetish kerak.","p":294,"k":"Qarilikdan oldin yoshlikni; 2. Kasallikdan oldin sog'liqni;","l":2,"o":["Boylikning","Bo'sh vaqtning","Yoshlikning","Sog'liqning"],"s":{"q":"Kasallikdan oldin nimaning qadriga yetamiz?","e":"Kasallikdan oldin sog'liqni qadrlaymiz.","o":["💰 Boylik","🕐 Bo'sh vaqt","🧒 Yoshlik","💪 Sog'liq"]}},{"t":"tf","q":"Abu Ali ibn Sino 18 yoshiga qadar juda ko'p ilmlarni egallagan.","a":true,"e":"Ha, Ibn Sino yoshligini g'animat bilib, undan unumli foydalangan va yetuk olim bo'lgan.","p":296,"k":"Abu Ali ibn Sino 18 yoshiga qadar juda ko'p ilmlarni egallab","l":2,"s":{"q":"Ibn Sino 18 yoshgacha ko'p ilm olgan.","e":"U yoshligini ilm olishga sarflagan."}},{"t":"mc","q":"Hikoyadagi Ali va uning oilasi nima uchun qiyin ahvolga tushib qoldi?","a":1,"e":"Ali boylarga o'xshashga urinib, kirimidan ko'p pul sarfladi. Isrof boylikni ham tugatadi.","p":297,"k":"Ali pulni behuda sarflash tufayli oilasi qiyin ahvolga tushib qoldi.","l":1,"o":["Kasal bo'lib qoldi","Pulni behuda sarfladi","Juda ko'p tejadi","Ishdan bo'shatildi"],"s":{"q":"Hikoyadagi Ali nega qiyin ahvolga tushdi?","e":"Isrof boylikni ham tugatadi.","o":["🤒 Kasal bo'ldi","💸 Pulni isrof qildi","🐷 Ko'p tejadi","🚪 Ishdan ketdi"]}},{"t":"tf","q":"Tejamkorlik bu baxillikning o'zi.","a":false,"e":"Noto'g'ri. Tejamkor faqat keraksiz xarajatdan saqlanadi, baxil esa kerakli joyga ham pul ishlatmaydi.","p":301,"k":"Chunki tejamkorlik hech qachon baxillik sanalmaydi.","l":1,"s":{"q":"Tejamkorlik — bu baxillik.","e":"Yo'q, tejamkor faqat keraksiz xarajat qilmaydi."}},{"t":"mc","q":"Kitobga ko'ra, saxiylik nima?","a":2,"e":"Saxiylik bag'rikenglik bo'lib, lozim miqdordan biroz ko'proq sarflashdir. U isrof emas.","p":301,"k":"pulni lozim bo'lgan miqdordan biroz ko'proq sarflashni bildiradi.","l":2,"o":["Ne'matni behuda sarflash","O'zganing molini ulashish","Lozimdan biroz ko'proq berish","Hech kimga bermaslik"],"s":{"q":"Saxiylik nima?","e":"Saxiylik — lozimdan biroz ko'p berish, isrof emas.","o":["💸 Behuda sarflash","🤲 O'zganikini berish","🎁 Biroz ortiq berish","✋ Hech bermaslik"]}},{"t":"mc","q":"\"Baxillik oqibati\" qissasida aka-ukalar kambag'allarga meva bermaslikka kelishgach, bog'ga nima bo'ldi?","a":3,"e":"Bog' baxillik uchun kuydirildi. Ota esa mevani ulashgani uchun bog'iga baraka kirgan edi.","p":303,"k":"Shu kechasi boqqa yondiruvchi bo'ron yog'ildi.","l":1,"o":["Hosili ikki baravar oshdi","Kambag'allarga berildi","Sotib yuborildi","Bo'ron kuydirib yubordi"],"s":{"q":"Baxil aka-ukalar bog'iga nima bo'ldi?","e":"Baxillik bog'ni kuydirdi, ulashish baraka beradi.","o":["🍎 Hosil oshdi","🤲 Ulashildi","💵 Sotildi","🔥 Bo'ron kuydirdi"]}},{"t":"tf","q":"Tekin yoki arzon ne'matlarni, masalan suvni, xohlagancha ishlataversa bo'ladi.","a":false,"e":"Noto'g'ri. Ichimlik suvi eng qadrli ne'matdir. Har bir ne'matning qadriga yetish kerak.","p":300,"k":"tekin yoki arzon ne'matlarni xohlagancha ishlataveradilar. Bu noto'g'ri.","l":2,"s":{"q":"Suvni xohlagancha ishlatsa bo'ladi.","e":"Yo'q, suv eng qadrli ne'mat, uni tejaymiz."}},{"t":"mc","q":"Kitobga ko'ra, ko'p uxlash bolani qanday qilib qo'yadi?","a":0,"e":"Ko'p uxlagan bolaning qo'li ishga bormaydi. Uyquda ham me'yorni saqlash kerak.","p":304,"k":"Ko'p uxlash bolani dangasa qilib qo'yadi.","l":1,"o":["Dangasa","Kuchli","Aqlli","Tirishqoq"],"s":{"q":"Ko'p uxlash bolani qanday qiladi?","e":"Ko'p uxlash dangasa qiladi, uyquda ham me'yor.","o":["😴 Dangasa","💪 Kuchli","🧠 Aqlli","🐝 Tirishqoq"]}},{"t":"mc","q":"Ko'z tez toliqmasligi uchun televizor ekranidan qancha uzoqda o'tirish kerak?","a":2,"e":"Ko'z charchamasligi uchun ekrandan kamida uch metr uzoqda o'tirish tavsiya etiladi.","p":306,"k":"televizor ekranidan kamida uch metr uzoqlikda o'tirish kerak.","l":2,"o":["Bir qarich","Yarim metr","Kamida uch metr","Ekranga yaqin"],"s":{"q":"Televizordan qancha uzoqda o'tiramiz?","e":"Ko'z charchamasin: kamida 3 metr uzoqda o'tiramiz.","o":["✋ Bir qarich","📏 Yarim metr","📺 Kamida 3 metr","👀 Ekranga yaqin"]}},{"t":"tf","q":"Boshqalarning baxtsizligi va kulfatidan xursand bo'lish yomon sifatdir.","a":true,"e":"To'g'ri. Bu yomonlikka sabab bo'ladigan sifatlardan biri, undan uzoq yurish kerak.","p":307,"k":"O'zgalarning baxtsizligi va kulfatidan xursand bo'lish.","l":1,"s":{"q":"Birovning kulfatiga xursand bo'lish yomon.","e":"Bunday yomon sifatdan uzoq yuramiz."}}],"cards":[{"t":"Vaqt g'animat, o'tsa nadomat.","p":295},{"t":"Yo'qotilgan oltin topilar, yo'qotilgan vaqt topilmas.","p":295},{"t":"Shamini kunduzi yondirgan odamning tuni qorong'u bo'ladi.","p":301}],"story":[{"e":"⏳","t":"O'tgan vaqt hech qachon qaytib kelmaydi.","p":294},{"e":"📚","t":"Yoshlikni ilm va hunar o'rganishga sarflaymiz.","p":296},{"e":"💰","t":"Isrof ham, baxillik ham yomon.","p":298},{"e":"😴🍽","t":"Ovqat, uyqu, o'yin — hammasida me'yor kerak.","p":304}]},{"id":14,"title":"Ilm — yutuq kaliti","icon":"📚","pages":[308,320],"lesson":[{"t":"Barcha yutuq va muvaffaqiyatlar kaliti ilmdir. Ilm bilan birga odob-axloqli ham bo'lish kerak.","p":308},{"t":"Hech kim olim bo'lib tug'ilmaydi. Har kuni oz-ozdan o'rgansa, odam yetuk ilm egasi bo'ladi.","p":310},{"t":"Ilm olish sirlari: sabr, iroda, qiziquvchanlik, darsda tanaffus, vaqtida ovqat va uyqu.","p":313},{"t":"Avval ona tilini yaxshi bilish, keyin chet tillarini o'rganish kerak. Chet tili yangi ilm eshiklarini ochadi.","p":317},{"t":"Aqlli odam avval maslahatlashib, so'ng ishga qo'l uradi.","p":318},{"t":"Ko'p so'zlash bilan odam dono bo'lmaydi, ko'p tinglab dono bo'ladi.","p":319}],"qs":[{"t":"mc","q":"Kitobga ko'ra, barcha yutuq va muvaffaqiyatlarning kaliti nima?","a":2,"e":"Hayotda har narsaning kaliti bor, yutuqlarning kaliti esa ilmdir.","p":308,"k":"Barcha yutuq va muvaffaqiyatlar kaliti ilmdir.","l":1,"o":["Boylik","Kuch","Ilm","Omad"],"s":{"q":"Yutuqlarning kaliti nima?","e":"Barcha yutuqlarning kaliti ilmdir.","o":["💰 Boylik","💪 Kuch","📚 Ilm","🍀 Omad"]}},{"t":"tf","q":"Ilmli, lekin xulqi yomon va boshqalarga ozor beradigan odamning ilmidan foyda yo'q.","a":true,"e":"To'g'ri. Ilm olish bilan birga go'zal odoblarga ham ega bo'lish kerak.","p":309,"k":"boshqalarga ozor bersa, uning egallagan ilmidan foyda yo'q.","l":2,"s":{"q":"Ilmli, ammo xulqi yomon odamning ilmidan foyda yo'q.","e":"Ilm bilan birga odobli ham bo'lamiz."}},{"t":"mc","q":"Ibn Abbos shuncha ilmga nima bilan erishganini aytdi?","a":0,"e":"U savol beruvchi til, biluvchi qalb va chidamli o'qituvchi bilan ilmga erishgan. Savol berish ilmga yo'l ochadi.","p":309,"k":"Savol beruvchi til, biluvchi qalb va chidamli o'qituvchi bilan.","l":2,"o":["Savol beruvchi til bilan","Ko'p uxlash bilan","Boylik bilan","Tez o'qish bilan"],"s":{"q":"Ibn Abbos ilmga nima bilan erishdi?","e":"Savol berish ilmga yo'l ochadi.","o":["❓ Savol berib","😴 Ko'p uxlab","💰 Boylik bilan","⚡ Tez o'qib"]}},{"t":"tf","q":"Kitobga ko'ra, bilmaslik eng katta aybdir.","a":false,"e":"Noto'g'ri. Bilmaganlik ayb emas, bilishga intilmaslik aybdir.","p":310,"k":"Bilmaganlik ayb emas, bilishga intilmaslik ayb.","l":1,"s":{"q":"Bilmaslik eng katta aybdir.","e":"Yo'q, bilishga intilmaslik aybdir."}},{"t":"mc","q":"Navoiy bobomiz: \"Oz-oz o'rganib ... bo'lur\" degan. Nuqtalar o'rnida nima?","a":3,"e":"Ilm asta-sekin o'zlashtiriladi: oz-oz o'rgangan odam dono bo'ladi.","p":310,"k":"Navoiy bobomiz esa: “Oz-oz o'rganib dono bo'lur,","l":1,"o":["boy","mashhur","katta","dono"],"s":{"q":"\"Oz-oz o'rganib ... bo'lur\". Nima?","e":"Oz-oz o'rgangan odam dono bo'ladi.","o":["💰 Boy","⭐ Mashhur","📏 Katta","🦉 Dono"]}},{"t":"mc","q":"Umar ibn Abdulaziz huzuridagi bola: inson qaysi ikki kichik a'zosi bilan insondir, dedi?","a":1,"e":"Bola qalbi va tili bilan inson qadrli bo'lishini aytdi. Ilm yoshga emas, bilimga bog'liq.","p":312,"k":"Inson ikki kichik a'zosi – qalbi va tili bilan insondir.","l":2,"o":["Qo'li va oyog'i","Qalbi va tili","Ko'zi va qulog'i","Yoshi va boyligi"],"s":{"q":"Bola: inson qaysi ikki a'zosi bilan inson?","e":"Inson qalbi va tili bilan qadrli.","o":["✋ Qo'li, oyog'i","💗 Qalbi, tili","👀 Ko'zi, qulog'i","🎂 Yoshi, boyligi"]}},{"t":"tf","q":"Darsdagi tanaffusni televizor ko'rib yoki kompyuter o'ynab o'tkazish kerak.","a":false,"e":"Noto'g'ri. Tanaffusni toza havoda yurish va jismoniy mashqlar bilan o'tkazish kerak.","p":314,"k":"toza havoda yurish va jismoniy mashqlar qilish bilan o'tkazish kerak.","l":1,"s":{"q":"Tanaffusda televizor ko'rish kerak.","e":"Yo'q, tanaffusda toza havoda yurib, mashq qilamiz."}},{"t":"mc","q":"Imomi A'zam chuqur bilim egasi bo'lishining sirini qanday tushuntirdi?","a":0,"e":"U bilmaganini diqqat bilan tinglab o'rgangan, bilganini esa maroq bilan takrorlagan.","p":314,"k":"Bilmaganimni o'rganish uchun diqqat bilan tingladim,","l":2,"o":["Diqqat bilan tingladim","Kam o'qidim","Hech savol bermadim","Ko'p uxladim"],"s":{"q":"Imomi A'zam qanday qilib ko'p bildi?","e":"U diqqat bilan tinglab, bilganini takrorlagan.","o":["👂 Diqqat tingladi","📕 Kam o'qidi","🤐 Savol bermadi","😴 Ko'p uxladi"]}},{"t":"tf","q":"Ko'p uxlagan odam ko'p dam oladi, shuning uchun imkon qadar ko'p uxlash foydali.","a":false,"e":"Noto'g'ri. Ko'p uxlagan odam vaqt yo'qotadi va dangasa bo'lib qoladi. Me'yorida va vaqtida uxlash kerak.","p":316,"k":"ko'p uxlagan odam ham vaqt yo'qotadi, ham dangasa bo'lib qoladi.","l":2,"s":{"q":"Imkon qadar ko'p uxlash foydali.","e":"Yo'q, ko'p uxlagan vaqt yo'qotadi, dangasa bo'ladi."}},{"t":"mc","q":"Kitobga ko'ra, inson eng avvalo qaysi tilni yaxshi bilib olishi kerak?","a":3,"e":"Ona tili eng kerakli tildir. Uni o'rganib olgach, chet tillarini o'rganish mumkin.","p":317,"k":"inson eng avvalo o'z ona tilini yaxshilab bilib olishi kerak.","l":1,"o":["Ingliz tilini","Rus tilini","Hech qaysini","Ona tilini"],"s":{"q":"Avval qaysi tilni yaxshi bilish kerak?","e":"Avval ona tili, keyin chet tillari.","o":["🌍 Ingliz tili","🌏 Rus tili","🚫 Hech qaysi","🏠 Ona tili"]}},{"t":"mc","q":"Aqlli odam ishga qo'l urishdan oldin nima qiladi?","a":2,"e":"Aqlli odam avval maslahatlashadi, ahmoq esa avval ishga qo'l urib, keyin maslahatlashadi.","p":318,"k":"Aqlli odam avval maslahatlashib, so'ng ishga qo'l uradi.","l":2,"o":["Darrov boshlaydi","Jahl qiladi","Maslahatlashadi","Hech kimni tinglamaydi"],"s":{"q":"Aqlli odam ishdan oldin nima qiladi?","e":"Avval maslahat, keyin ish.","o":["🏃 Darrov boshlaydi","😠 Jahl qiladi","🤝 Maslahatlashadi","🙉 Tinglamaydi"]}},{"t":"tf","q":"\"O'g'ri topildi\" hikoyasida Abu Hanifa o'g'rini boshini paypaslaganidan tanib oldi.","a":true,"e":"To'g'ri. Imom aql bilan o'g'rini topdi va tovus egasiga qaytarildi.","p":319,"k":"jamoatdan bir odam boshini paypaslaganini ko'rdi.","l":1,"s":{"q":"Abu Hanifa o'g'rini boshini paypaslaganidan tanidi.","e":"Imom aql bilan o'g'rini topdi."}}],"cards":[{"t":"Qiziqish ilmning eshigidir.","p":309},{"t":"Bilim shunday boylikki, uni hech kim tortib ololmaydi.","p":310},{"t":"Pulni ishlatsang kamayadi, aqlni ishlatsang sayqal topib ko'payadi.","p":318}],"story":[{"e":"🔑📚","t":"Ilm — barcha yutuqlarning kaliti.","p":308},{"e":"🐢","t":"Oz-oz o'rganib, dono bo'lamiz.","p":310},{"e":"🏠🌍","t":"Avval ona tilini, keyin chet tilini o'rganamiz.","p":317},{"e":"🤝","t":"Aqlli odam avval maslahatlashadi.","p":318}]},{"id":15,"title":"Halollik va rostgo'ylik","icon":"🤝","pages":[320,334],"lesson":[{"t":"O'z haqingni tani, birovning haqidan qo'rq. Tarozidan urib qolish birovning haqini yeyishdir.","p":320},{"t":"Hazrati Umar davlat chirog'ini o'z suhbati uchun ishlatmadi, o'z pulidagi chiroqni yoqdi.","p":322},{"t":"Shijoat — burchni bajarish yo'lida dovyuraklik bilan xatarga qarshi turish. Qo'rqoqlik yomon xislat.","p":323},{"t":"Dangasalik insonni xor qiladi. Tirishqoq bolalar darsini vaqtida qilib, ota-onasiga yordamlashadi.","p":326},{"t":"Topib olingan narsa omonat, uni egasiga qaytarish kerak. Do'st sirini saqlash ham omonatdir.","p":328},{"t":"Rost so'zlagan odam ko'pchilik ishonchini qozonadi. Berilgan va'da qarz kabidir.","p":333}],"qs":[{"t":"mc","q":"Quyidagilardan qaysi biri birovning haqini yeyish hisoblanadi?","a":3,"e":"Olish-sotishda tarozidan urib qolish xaridorni aldash va birovning haqini yeyishdir.","p":320,"k":"olish va sotishda tarozidan urib qolish,","l":1,"o":["Halol savdo qilish","O'z haqini olish","Narsani asrash","Tarozidan urib qolish"],"s":{"q":"Qaysi biri birovning haqini yeyish?","e":"Tarozidan urib qolish — xaridorni aldash.","o":["🤝 Halol savdo","✅ O'z haqini olish","📦 Narsani asrash","⚖️ Tarozidan urish"]}},{"t":"mc","q":"Xazinachi Umarning o'g'liga mato berganida, Hazrati Umar nima qilgan bo'lardi?","a":0,"e":"Hazrati Umar xazina moliga juda ehtiyot bo'lgan. Davlat moli shaxsiy ishga ishlatilmaydi.","p":322,"k":"men uni o'sha zahoti ishdan bo'shatgan bo'lar edim,","l":2,"o":["Ishdan bo'shatardi","Uni mukofotlardi","Rahmat aytardi","Yana mato so'rardi"],"s":{"q":"O'g'liga xazinadan mato bersa, Umar nima qilardi?","e":"Davlat moli shaxsiy ishga ishlatilmaydi.","o":["🚪 Ishdan bo'shatardi","🏅 Mukofotlardi","🙏 Rahmat aytardi","🧵 Yana so'rardi"]}},{"t":"tf","q":"Hazrati Umar do'sti bilan suhbatlashish uchun davlat chirog'ini o'chirib, o'z pulidagi chiroqni yoqdi.","a":true,"e":"To'g'ri. Davlat chirog'i faqat davlat ishi uchun halol edi, shaxsiy suhbatga esa o'z chirog'ini yoqdi.","p":322,"k":"o'z pulimga olingan ikkinchi chiroqni yoqib qo'ydim.","l":1,"s":{"q":"Umar suhbat uchun o'z pulidagi chiroqni yoqdi.","e":"Davlat chirog'i faqat davlat ishi uchun."}},{"t":"mc","q":"Dengiz qirg'og'idagi shijoatli yigit nima qildi?","a":2,"e":"Yigit dovyuraklik bilan suvga otilib, cho'kayotgan odamni qutqardi. Bu haqiqiy shijoat.","p":323,"k":"Cho'kayotgan odamni qutqarib qolgan bu yigit shijoatli","l":1,"o":["Faqat qarab turdi","Uyiga ketib qoldi","Cho'kayotganni qutqardi","Odamlarni chaqirdi"],"s":{"q":"Dengiz bo'yidagi yigit nima qildi?","e":"Yigit suvga otilib, odamni qutqardi — bu shijoat.","o":["👀 Qarab turdi","🏠 Uyiga ketdi","🏊 Qutqarib oldi","📣 Odam chaqirdi"]}},{"t":"tf","q":"Matonatsiz odam boshlagan ishini qiyinchilik bo'lsa ham oxirigacha yetkazadi.","a":false,"e":"Noto'g'ri. Matonatsiz odam salgina qiyinchilikdan so'ng ishni tashlab qo'yadi. Matonatli bo'lish kerak.","p":323,"k":"Matonatsiz odam bir ishni boshlab, biroq salgina qiyinchilikdan so'ng uni tashlab qo'yadi.","l":2,"s":{"q":"Matonatsiz odam ishni oxirigacha yetkazadi.","e":"Yo'q, u salgina qiyinchilikda ishni tashlaydi."}},{"t":"mc","q":"Yosh Abdulloh ibn Zubayr nega boshqa bolalar kabi chetga chiqmadi?","a":1,"e":"Bola aybi yo'qligini va yo'l tor emasligini aytdi. Hazrati Umar uning shijoatidan xursand bo'ldi.","p":324,"k":"aybim yo'qki, sizdan qo'rqsam, yo'l ham tor emaski,","l":2,"o":["Umarni tanimadi","Aybi yo'q, yo'l ham tor emas","Qo'rqib qotib qoldi","O'ynashni istadi"],"s":{"q":"Kichik Abdulloh nega chetga chiqmadi?","e":"Aybi yo'q bola qo'rqmadi, Umar xursand bo'ldi.","o":["🤷 Umarni tanimadi","✅ Aybi yo'q edi","🥶 Qo'rqib qotdi","🎈 O'ynamoqchi edi"]}},{"t":"mc","q":"Horun ar-Rashid ko'chaga qo'y ostirib, odamlarga nimani tushuntirdi?","a":0,"e":"Yomonlik yomon hid kabi hammaga yetadi. Yaxshilar yomonlikka qarshi turishi kerak.","p":326,"k":"Yomonliklar ham yomon hidga o'xshaydi.","l":2,"o":["Yomonlik hammaga ta'sir qiladi","Har kim faqat o'ziga javobgar","Nasihat keraksiz narsa","Qo'y go'shti foydali"],"s":{"q":"Horun ar-Rashid qo'y ostirib nimani tushuntirdi?","e":"Yomonlik yomon hid kabi hammaga yetadi.","o":["🦨 Yomonlik hammaga","👤 Har kim o'ziga","🙉 Nasihat keraksiz","🍖 Go'sht foydali"]}},{"t":"tf","q":"Maktab hovlisidan topib olingan narsa topgan bolaning mulki bo'ladi.","a":false,"e":"Noto'g'ri. Topilgan narsa omonat. Egasini qidirib, unga qaytarish kerak.","p":327,"k":"u sening qo'lingdagi omonatdir. U sening mulking emas.","l":1,"s":{"q":"Topilgan narsa topgan bolaniki bo'ladi.","e":"Yo'q, topilgan narsa omonat, egasiga qaytaramiz."}},{"t":"mc","q":"Hikoyadagi kambag'al odam boyning orqasidan yugurib borib nima dedi?","a":3,"e":"U omonatga vafodor edi. Boy uning to'g'riligi uchun yana bir tilla tanga berdi.","p":329,"k":"siz menga tilla tanga berdingiz, ehtimol bu yanglish bo'lgandir.","l":1,"o":["Yana pul so'radi","Rahmat aytib ketdi","Tangani yashirdi","Tilla xato berilganini aytdi"],"s":{"q":"Kambag'al boyning ortidan yugurib nima dedi?","e":"U omonatga vafodor edi, boy uni mukofotladi.","o":["💰 Yana pul so'radi","🙏 Rahmat aytdi","🙈 Tangani yashirdi","🪙 Tilla xato berildi"]}},{"t":"mc","q":"Aldoqchi Farrux uzukni olganini qanday qilib bildirib qo'ydi?","a":2,"e":"Uzukni olmagan bo'lsa, daraxt qayerdaligini bilmas edi. Yolg'on oxiri fosh bo'ladi.","p":330,"k":"Chunki kashtan daraxti bu erdan judayam uzoq.","l":2,"o":["Uzukni qaytarib berdi","Guvoh topildi","Daraxt uzoqligini aytdi","O'zi tan oldi"],"s":{"q":"Aldoqchi Farrux uzukni olganini qanday bildirdi?","e":"Yolg'on oxiri fosh bo'ladi.","o":["💍 Uzukni qaytardi","👁 Guvoh topildi","🌳 Daraxt uzoq dedi","🗣 O'zi tan oldi"]}},{"t":"tf","q":"\"Yolg'onchi bola\" hikoyasida bola ikkinchi kuni chindan yordam so'raganda, bolalar unga ishonmadi.","a":true,"e":"To'g'ri. Kecha hazillashib aldagani uchun bolalar uni yana masxara qilyapti deb o'ylashdi. Yolg'on ishonchni yo'qotadi.","p":332,"k":"Bolalar o'tgan kungidek bugun ham bizni masxara qilyapti deb o'ylab,","l":1,"s":{"q":"Yolg'onchi bola chin yordam so'raganda, ishonishmadi.","e":"Yolg'on ishonchni yo'qotadi."}},{"t":"tf","q":"Kitobga ko'ra, berilgan va'da qarz kabidir.","a":true,"e":"To'g'ri. Qarzni vaqtida qaytarish shart bo'lganidek, va'daga vafo qilish ham shart.","p":333,"k":"shuni bilki, berilgan va'da qarz kabidir.","l":2,"s":{"q":"Berilgan va'da qarz kabidir.","e":"Qarz kabi, va'dani ham albatta bajaramiz."}}],"cards":[{"t":"Daraxt yaprog'i bilan go'zal, odam – mehnati bilan.","p":327},{"t":"Egri daraxtning soyasi ham egri bo'ladi.","p":332},{"t":"Rostgo'ylik insonni ulug'lar martabasiga ko'taradi.","p":332}],"story":[{"e":"⚖️","t":"Birovning haqini yemaymiz, tarozidan urmaymiz.","p":320},{"e":"🦁","t":"Shijoatli odam xatardan qo'rqmay burchini bajaradi.","p":323},{"e":"🎒","t":"Topilgan narsa omonat, uni egasiga qaytaramiz.","p":328},{"e":"🗣","t":"Rostgo'yga hamma ishonadi. Va'da — qarz kabi.","p":333}]},{"id":16,"title":"Sabr, qanoat va kamtarlik","icon":"🌱","pages":[334,346],"lesson":[{"t":"Sabrli va vazmin odam har so'zini o'ylab gapiradi. Shoshib qilingan ish afsus-nadomatga olib boradi.","p":335},{"t":"Qanoat — bor narsaga rozi bo'lish. U dangasalik emas. Qanoatning ziddi ochko'zlikdir.","p":337},{"t":"Hamma xato qiladi. Kechirimlilik dushmanni ham do'stga aylantirishi mumkin.","p":339},{"t":"Kamtarlik ulug' martabalarga erishtiradi, manmanlik esa xorlikka yetaklaydi.","p":341},{"t":"Ne'matlar uchun shukr qilib, ularni, ayniqsa tana a'zolarimizni avaylab-asrash kerak.","p":342},{"t":"Yaxshi insonlarga havas qilish yaxshi, hasad esa eng yomon illatdir.","p":344}],"qs":[{"t":"mc","q":"Dono xalqimiz aytadi: \"Avval o'yla, keyin ...\". Nuqtalar o'rnida nima?","a":1,"e":"Har bir gapni shoshilmasdan, o'ylab gapirish kerak. Sabrli odam xatodan saqlanadi.","p":335,"k":"Dono xalqimiz bejizga “avval o'yla, keyin so'yla” demagan.","l":1,"o":["o'yna","so'yla","uxla","yugur"],"s":{"q":"\"Avval o'yla, keyin ...\". Nima?","e":"Har bir gapni o'ylab gapiramiz.","o":["⚽ O'yna","🗣 So'yla","😴 Uxla","🏃 Yugur"]}},{"t":"tf","q":"Kitobga ko'ra, g'azabi kelganda o'zini bosa oladigan kishi eng kuchlidir.","a":true,"e":"To'g'ri. Haqiqiy kuch — jahl chiqqanda o'zini tuta bilish va nafsini to'g'ri yo'lga boshlash.","p":335,"k":"o'z nafsini to'g'ri yo'lga boshlaydigan kishi eng kuchlidir.","l":2,"s":{"q":"Jahli chiqqanda o'zini tutgan odam eng kuchli.","e":"Haqiqiy kuch — jahlni bosa olish."}},{"t":"tf","q":"Qanoat qilish — dangasa bo'lib o'tirish degani.","a":false,"e":"Noto'g'ri. Qanoat bor narsaga rozi bo'lishdir, u g'ayrat-shijoatga teskari emas.","p":336,"k":"Ba'zilar qanoatni noto'g'ri tushunib, uni dangasa bo'lib o'tirishdir deb o'ylaydi.","l":1,"s":{"q":"Qanoat — dangasa bo'lib o'tirish.","e":"Yo'q, qanoat — bor narsaga rozi bo'lish."}},{"t":"mc","q":"Kitobga ko'ra, qanoatning ziddi nima?","a":3,"e":"Qanoat me'yorda yashashni o'rgatadi, ochko'zlik esa chegaradan chiqishga sabab bo'ladi.","p":337,"k":"Qanoat insonga o'sha me'yorda yashashni o'rgatadi. Qanoatning ziddi ochko'zlikdir.","l":1,"o":["Saxiylik","Sabr","Kamtarlik","Ochko'zlik"],"s":{"q":"Qanoatning ziddi nima?","e":"Qanoatning ziddi — ochko'zlik.","o":["🎁 Saxiylik","⏳ Sabr","🙇 Kamtarlik","🤑 Ochko'zlik"]}},{"t":"mc","q":"Sa'd ibn Abu Vaqqos o'g'liga boylik bilan birga yana nimani so'rashni nasihat qildi?","a":0,"e":"Qanoatsiz odam boy bo'lolmaydi. Qanoat bitmas-tuganmas boylikdir.","p":336,"k":"boylik bilan birga qanoat ham so'ra.","l":2,"o":["Qanoatni","Shon-shuhratni","Ko'proq boylikni","Kuch-quvvatni"],"s":{"q":"Sa'd o'g'liga boylik bilan yana nimani so'ra dedi?","e":"Qanoat bitmas-tuganmas boylikdir.","o":["😊 Qanoatni","⭐ Shon-shuhratni","💰 Ko'proq boylik","💪 Kuch-quvvatni"]}},{"t":"mc","q":"Muhammad ibn Yamoniy so'ragan olti toifa kishi qanday bir xil javob berdi?","a":2,"e":"Tabiblar ham, olimlar ham oz yeyish foydali deyishdi. Taomda me'yor kerak.","p":338,"k":"Ular: “Ochlik va oz eyish”, deyishdi.","l":2,"o":["Ko'p uxlash","Mazali taomlar","Ochlik va oz yeyish","Ko'p ovqat yeyish"],"s":{"q":"Olti xil kishi qanday bir xil javob berdi?","e":"Taomda me'yor kerak: oz yeyish foydali.","o":["😴 Ko'p uxlash","🍰 Mazali taom","🥣 Ochlik, oz yeyish","🍗 Ko'p yeyish"]}},{"t":"mc","q":"Abu Hanifadan \"Otning tuyoqlari nechta?\" deb so'rashganda u nima qildi?","a":3,"e":"Biror narsani aniq bilsa ham, yana bir mulohaza qilib javob berish kerak. \"Yetti o'lchab, bir kes\".","p":339,"k":"Imom otdan tushib, otning oyoqlarini sanab ko'rdilar","l":1,"o":["Darrov javob berdi","Javob bermadi","Kulib qo'ydi","Otdan tushib sanadi"],"s":{"q":"Otning tuyog'i nechta? Abu Hanifa nima qildi?","e":"Yetti o'lchab, bir kes — o'ylab javob beramiz.","o":["⚡ Darrov aytdi","🤐 Javob bermadi","😄 Kulib qo'ydi","🐴 Tushib sanadi"]}},{"t":"tf","q":"Kechirimlilik dushmanni do'stga aylantirishi mumkin.","a":true,"e":"To'g'ri. Bag'ritoshlik esa aksincha, do'stni dushmanga aylantirishi mumkin.","p":339,"k":"Kechirimlilik dushmanni do'stga, bag'ritoshlik esa do'stni dushmanga aylantirishi mumkin.","l":2,"s":{"q":"Kechirim dushmanni ham do'st qilishi mumkin.","e":"Bag'ritoshlik esa do'stni dushman qiladi."}},{"t":"mc","q":"\"Saroy qaerda?\" hikoyasida Vizantiyalik hokim nimadan hayratda qoldi?","a":0,"e":"Hazrati Umar kamtarin bo'lgani uchun o'ziga saroy ham, taxt ham qurdirmagan edi.","p":342,"k":"Kamtarin bo'lganidan o'zi uchun taxt qurdirmagan edi.","l":2,"o":["Umarning kamtarligidan","Saroy go'zalligidan","Posbonlar ko'pligidan","Taxtning kattaligidan"],"s":{"q":"\"Saroy qayerda?\" hikoyasida hokim nimaga hayron bo'ldi?","e":"Umar kamtar edi, saroy ham, taxt ham qurdirmagan.","o":["🙇 Umar kamtarligiga","🏰 Saroy chiroyiga","💂 Posbonlarga","👑 Katta taxtga"]}},{"t":"tf","q":"Manmanlik insonni ulug' martabalarga erishtiradi.","a":false,"e":"Noto'g'ri. Manmanlik xorlikka yetaklaydi, ulug' martabaga esa kamtarlik erishtiradi.","p":341,"k":"Manmanlik insonni xorlikka etaklaydi. Kamtarlik seni ulug' martabalarga erishtiradi.","l":1,"s":{"q":"Manmanlik insonni ulug'laydi.","e":"Yo'q, manmanlik xor qiladi, kamtarlik ulug'laydi."}},{"t":"mc","q":"Kitobga ko'ra, havas nima?","a":2,"e":"Havas yaxshi insonlardagi fazilatlarni o'zida ham bo'lishini xohlash. U bizni yaxshilikka chorlaydi.","p":343,"k":"yaxshi insonlardagi fazilat va xislatlarni ko'rib, ularni o'zimizda ham bo'lishini xohlash","l":1,"o":["Birov yutug'ini ko'ra olmaslik","Boshqani kamsitish","Yaxshi fazilatni o'zida xohlash","Hech narsa qilmaslik"],"s":{"q":"Havas nima?","e":"Havas — yaxshi fazilatni o'zimizda ham istash.","o":["😒 Ko'ra olmaslik","👎 Kamsitish","🌟 Yaxshini istash","🛋 Hech ish qilmaslik"]}},{"t":"tf","q":"Hasadgo'y odam boshqalar ham yutuqqa erishishini chin dildan xohlaydi.","a":false,"e":"Noto'g'ri. Hasadgo'y yaxshilik boshqalardan olinib, faqat o'ziga berilishini istaydi. Hasaddan uzoq bo'laylik.","p":344,"k":"hasadgo'y esa odamlardan bu yaxshilik olinib, faqat o'zigagina berilishini istaydi.","l":2,"s":{"q":"Hasadgo'y boshqalar yutishini chin dildan xohlaydi.","e":"Yo'q, hasadgo'y yaxshilik faqat o'ziga bo'lsin deydi."}}],"cards":[{"t":"Sabrning avvali achchiq, oxiri esa shirin.","p":336},{"t":"Yomon kunda sabr qilgan odam yaxshi kunga tez etadi.","p":336},{"t":"Uch sifat uch xil natija keltiradi: muloyimlik – ulug' martaba, qanoat – rohat, tavoze' – e'zoz keltiradi.","p":346}],"story":[{"e":"🤔","t":"Avval o'yla, keyin so'yla.","p":335},{"e":"🌱","t":"Sabrning avvali achchiq, oxiri shirin.","p":336},{"e":"😊","t":"Qanoat — bor narsaga rozi bo'lish.","p":337},{"e":"🙇","t":"Kamtarlik ulug'laydi, manmanlik xor qiladi.","p":341}]}]};
